TP.register({id:"lp8-g7",lp:8,grade:"7",mode:"curriculum",checks:7,nextGrade:"8th grade",build(E){const F=E.F;const ico=(n,s=72)=>F.icon(n,s);const STORY_TITLE="The Frame";const STORY=`<p>The kit came in a box eleven feet long with a picture of two smiling adults on the lid and a line printed underneath: ASSEMBLY TIME 4 HOURS, TWO PERSON JOB.</p>
<p>Dovie read that line about nine times.</p>
<p>She had asked for the hoop house in October. She had written the proposal, found the grant, measured the site, and argued with the custodian about the drainage, and the thing she wanted now, more than the hoop house, was to be the one who put it up.</p>
<p>On the first Saturday she got four of the twelve ribs into the ground sockets by herself, which took three hours and a method involving her knee that she would not have described to anyone. The fifth rib went in crooked. She pulled it, straightened the socket, and set it again.</p>
<p>The sixth rib was the one that bent.</p>
<p>It did not snap. It took on a slight flat spot about a third of the way up, the kind you only see if you sight down the pipe, and Dovie sat down on the grass and sighted down it for a long time.</p>
<p>Selena found her there at four o'clock. Selena had not been asked, and she did not ask anything either. She picked up the seventh rib, carried it to the socket, and stood holding it upright, waiting.</p>
<p>Dovie looked at her.</p>
<p>&ldquo;It is a two person job,&rdquo; Selena said. &ldquo;It says so on the box.&rdquo;</p>
<p>&ldquo;I know what it says on the box.&rdquo;</p>
<p>&ldquo;Then hold the other end.&rdquo;</p>
<p>They had the remaining six ribs in before five thirty. With one person steadying and one person seating the pipe, each rib took about four minutes. Dovie did that arithmetic on the walk home and did not enjoy it.</p>
<p>In June the hoop house held forty-one trays, a thermometer, and a sign Mr. Abara had made that said DOVIE MARCHETTI, PROPOSAL AND BUILD. She looked at the sign for a while. Then she went and found a marker and added two words.</p>
<p>She did not tell anybody. Selena saw it in September.</p>`;const story=small=>`<h3 style="margin:0 0 6px;color:var(--sea)">${STORY_TITLE}</h3><div class="passage${small?" sm":""}">${STORY}</div>`;const ART_TITLE="What the Packet Does Not Tell You";const ART=`<p>Every seed in a packet is a living thing in a paused state, and the pause does not last forever.</p>
<p>Seed companies print a date on the packet, and in most of the United States they are required to. What that date records is when the seed was put into the envelope. It is not a promise about what will come up.</p>
<p>How long a seed stays viable depends first on the kind. Onion and parsnip seed is usually poor by the end of its second year. Tomato, cucumber, and lettuce seed often germinates well after five. Those are not rules, they are tendencies, and they are tendencies measured under good storage.</p>
<p>Storage is the second thing. The working rule among seed savers is that the storage temperature in degrees Fahrenheit plus the relative humidity in percent should stay under 100. Seed in a paper envelope in a garage that hits 95 degrees in August is being aged on purpose, whatever the packet says.</p>
<p>The third thing is that none of this has to be guessed at. A germination test takes ten seeds, a damp paper towel, a plastic bag, and about a week on top of the refrigerator. Count how many of the ten sprout. Six out of ten is a sixty percent germination rate, and that does not mean throw the packet away. It means sow the row thicker.</p>
<p>That is the part people miss. A germination test is not a pass or a fail. It is a number you plant with.</p>`;const article=small=>`<h3 style="margin:0 0 6px;color:var(--sea)">${ART_TITLE}</h3><div class="passage${small?" sm":""}">${ART}</div>`;const WRITE_DIR="Write on your paper for about 5 minutes. Then hold it up or read it to your teacher.";const checklist=items=>`<ul class="qlist" style="margin-top:14px">${items.map(x=>`<li>${x}</li>`).join("")}</ul>`;const lead=t=>`<p class="big" style="margin-top:0">${t}</p>`;const group=(inner,label)=>`<div style="text-align:center">${inner}<p class="fig-label" style="margin:4px 0 0">${label}</p></div>`;const factBox=(title,items)=>`<div style="border:3px dashed var(--line);border-radius:16px;background:var(--surface);padding:10px 20px;margin:14px 0"><p class="fig-label" style="margin:0 0 6px;text-align:left">${title}</p><ul style="margin:0;padding-left:1.2em;font-size:1.22rem;line-height:1.5">${items.map(x=>`<li>${x}</li>`).join("")}</ul></div>`;const bigTable=(head,rows,cap)=>`<div class="tool-scroll"><table class="chart" style="margin:14px auto;font-size:1.25rem">${cap?`<caption style="font-size:1.05rem;padding-bottom:6px">${cap}</caption>`:""}<tr>${head.map(h=>`<th style="text-align:center">${h}</th>`).join("")}</tr>${rows.map(r=>`<tr>${r.map((c,i)=>i?`<td style="text-align:center">${c}</td>`:`<th>${c}</th>`).join("")}</tr>`).join("")}</table></div>`;const CM=22;const T=(x,y,t,a)=>`<text x="${x}" y="${y}" text-anchor="${a||"middle"}" font-size="17" font-weight="700" fill="var(--ink)" paint-order="stroke" stroke="var(--surface)" stroke-width="4">${t}</text>`;const upperArc=(cx,cy,rCm,c)=>{const r=rCm*CM;return`<path d="M${cx-r} ${cy} A${r} ${r} 0 0 1 ${cx+r} ${cy}" fill="none" stroke="${c||"var(--sea)"}" stroke-width="2.4" stroke-dasharray="7 5"/>`};function noTriFig(){const ox=104,baseY=176,b=11*CM,W=510,H=218;const ax=ox,bx=ox+b;const la=70*Math.PI/180,ra=110*Math.PI/180;const lp=[ax+4*CM*Math.cos(la),baseY-4*CM*Math.sin(la)],rp=[bx+6*CM*Math.cos(ra),baseY-6*CM*Math.sin(ra)];return`<svg viewBox="0 0 ${W} ${H}" width="${W}" style="max-width:100%;height:auto" role="img" aria-label="A base segment 11 centimeters long. A dashed arc of radius 4 centimeters is drawn about its left end and a dashed arc of radius 6 centimeters about its right end. The two arcs do not meet.">
    ${upperArc(ax,baseY,4)}${upperArc(bx,baseY,6,"var(--coral)")}
    <line x1="${ax}" y1="${baseY}" x2="${bx}" y2="${baseY}" stroke="var(--fig-ink)" stroke-width="4"/>
    <circle cx="${ax}" cy="${baseY}" r="4.5" fill="var(--fig-ink)"/><circle cx="${bx}" cy="${baseY}" r="4.5" fill="var(--fig-ink)"/>
    <line x1="${ax}" y1="${baseY}" x2="${lp[0]}" y2="${lp[1]}" stroke="var(--sea)" stroke-width="2"/>
    <line x1="${bx}" y1="${baseY}" x2="${rp[0]}" y2="${rp[1]}" stroke="var(--coral)" stroke-width="2"/>
    ${T((ax+lp[0])/2-16,(baseY+lp[1])/2,"4 cm","end")}${T((bx+rp[0])/2+16,(baseY+rp[1])/2,"6 cm","start")}
    ${T((ax+bx)/2,baseY+26,"11 cm")}</svg>`}function triFig(){const ox=122,baseY=224,W=500,H=264;const ax=ox,bx=ox+9*CM;const px=ax+57/18*CM,py=baseY-Math.sqrt(25-57/18*(57/18))*CM;return`<svg viewBox="0 0 ${W} ${H}" width="${W}" style="max-width:100%;height:auto" role="img" aria-label="A base segment 9 centimeters long with a dashed arc of radius 5 centimeters about its left end and a dashed arc of radius 7 centimeters about its right end. The arcs meet at one point above the base, and a triangle is drawn to that point.">
    ${upperArc(ax,baseY,5)}${upperArc(bx,baseY,7,"var(--coral)")}
    <polygon points="${ax},${baseY} ${bx},${baseY} ${px},${py}" fill="var(--sea-soft)" fill-opacity=".75" stroke="var(--fig-ink)" stroke-width="3.5" stroke-linejoin="round"/>
    <circle cx="${px}" cy="${py}" r="5" fill="var(--coral)" stroke="var(--fig-ink)" stroke-width="2"/>
    ${T((ax+px)/2-14,(baseY+py)/2,"5 cm","end")}${T((bx+px)/2+14,(baseY+py)/2,"7 cm","start")}
    ${T((ax+bx)/2,baseY+26,"9 cm")}</svg>`}const FT=17;function ftPoly(pts,o){o=o||{};const xs=pts.map(p=>p[0]),ys=pts.map(p=>p[1]);const wFt=Math.max.apply(null,xs),hFt=Math.max.apply(null,ys);const ml=o.ml||40,mr=o.mr||48,mt=o.mt||28,mb=o.mb||40;const W=wFt*FT+ml+mr,H=hFt*FT+mt+mb;const X=x=>ml+x*FT,Y=y=>mt+(hFt-y)*FT;let s=`<svg viewBox="0 0 ${W} ${H}" width="${W}" style="max-width:100%;height:auto" role="img" aria-label="${o.alt||"A shape drawn to scale"}">`;s+=`<polygon points="${pts.map(p=>X(p[0])+","+Y(p[1])).join(" ")}" fill="var(--sea-soft)" stroke="var(--fig-ink)" stroke-width="3" stroke-linejoin="round"/>`;(o.dash||[]).forEach(d=>{s+=`<line x1="${X(d[0])}" y1="${Y(d[1])}" x2="${X(d[2])}" y2="${Y(d[3])}" stroke="var(--fig-ink)" stroke-width="2" stroke-dasharray="6 5"/>`});(o.labels||[]).forEach(l=>{s+=`<text x="${X(l[1])}" y="${Y(l[2])}" font-size="16" font-weight="700" text-anchor="${l[3]||"middle"}" dominant-baseline="${l[4]||"auto"}" fill="var(--ink)" paint-order="stroke" stroke="var(--surface)" stroke-width="4">${l[0]}</text>`});return s+"</svg>"}const trapBed=()=>ftPoly([[0,0],[9,0],[7,4],[2,4]],{alt:"A trapezoid bed with a bottom side of 9 feet, a top side of 5 feet, and a dashed height of 4 feet.",dash:[[2,4,2,0]],labels:[["9 ft",4.5,-1.2],["5 ft",4.5,4.6],["4 ft",2.45,2,"start","central"]]});const compBed=()=>ftPoly([[0,0],[6,0],[6,4],[3,7],[0,4]],{alt:"A bed made of a 6 foot by 4 foot rectangle with a triangle on top of it. The triangle has a base of 6 feet and a height of 3 feet.",dash:[[0,4,6,4],[3,7,3,4]],labels:[["6 ft",3,-1.2],["4 ft",6.5,2,"start","central"],["3 ft",3.45,5.5,"start","central"]]});const LOG_TITLE="Hoop house build log";const LOG_SRC="Kept by Mr. Abara for the grant report. Entries are made on site, in order.";const LOGDOC=`<p><strong>First Saturday, 9:05.</strong> Kit opened. 12 ribs, 12 ground sockets, cover and hardware all present. D. Marchetti working alone at her own request.</p>
<p><strong>12:10.</strong> Ribs 1 to 4 seated. Rib 5 pulled and reset once, socket out of plumb.</p>
<p><strong>13:40.</strong> Rib 6 seated. Flat spot in the pipe about one third of the way up. Not replaced: the kit carries no spare rib. Noted here for the grant report.</p>
<p><strong>16:00.</strong> Selena joined the build.</p>
<p><strong>17:25.</strong> Ribs 7 to 12 seated. Frame complete. No injuries, no damaged hardware.</p>
<p><strong>Cost to district: $0.</strong> Kit $377, covered by the $200 grant and twelve member contributions of $14.75.</p>`;const buildLog=()=>`<article><h3 style="margin:0 0 4px;color:var(--sea)">${LOG_TITLE}</h3><p class="src" style="margin:0 0 8px">${LOG_SRC}</p><div class="passage sm">${LOGDOC}</div></article>`;const P_SRC="Source P: letter to the site council from Ileana Brandt, parent and licensed heating and cooling technician.";const P_TEXT=`<p>I have read the club's numbers and I am not persuaded.</p>
<p>A hoop house is a piece of climate equipment. On seven days this spring the inside temperature went past 85 degrees with the roof vent shut, and seven is not a small number when a tray of seedlings can cook in one afternoon.</p>
<p>The club logged 310 hours. I believe that figure. Hours are not the same as coverage. A scheduled staff round happens whether or not anybody has a test that morning, and that is the whole of what $2,900 a year buys.</p>
<p>Two of the twelve members graduate in June. If the fourth of those seven warm days had fallen on a Saturday, we would be having a very different conversation this evening.</p>`;const Q_SRC="Source Q: letter to the site council from Dale Okafor, coordinator of the community garden.";const Q_TEXT=`<p>The community garden took in 620 seedlings from the hoop house this spring. That is more than we have ever received from a purchased source, and it cost the district nothing.</p>
<p>The kit was $377. Two hundred of that was a grant and the rest came from twelve students at $14.75 each. The students wrote the proposal, measured the site, and built the frame.</p>
<p>Every program run by students has gaps. Ours has them too. The question in front of the council is not whether there were seven warm days. The question is what $2,900 a year buys that twelve young people are not already doing for nothing.</p>`;const srcCard=(tag,head,body)=>`<article style="flex:1 1 320px;border:2px solid var(--line);border-radius:16px;padding:12px 16px;background:var(--surface)"><h3 style="margin:0 0 4px;color:var(--sea)">${tag}</h3><p class="src" style="margin:0 0 8px">${head}</p><div class="passage sm" style="margin:0">${body}</div></article>`;const twoLetters=()=>`<div style="display:flex;gap:16px;flex-wrap:wrap;margin-bottom:10px">${srcCard("Source P",P_SRC,P_TEXT)}${srcCard("Source Q",Q_SRC,Q_TEXT)}</div>`;function circleFig(){const W=300,H=300,cx=150,cy=146,r=108;let s=`<svg viewBox="0 0 ${W} ${H}" width="${W}" style="max-width:100%;height:auto" role="img" aria-label="A circular stepping stone with a line drawn right across it through the center, labeled 18 inches.">`;s+=`<circle cx="${cx}" cy="${cy}" r="${r}" fill="var(--sea-soft)" stroke="var(--fig-ink)" stroke-width="3"/>`;s+=`<line x1="${cx-r}" y1="${cy}" x2="${cx+r}" y2="${cy}" stroke="var(--fig-ink)" stroke-width="2.4" stroke-dasharray="7 5"/>`;s+=`<circle cx="${cx}" cy="${cy}" r="4.5" fill="var(--fig-ink)"/>`;s+=T(cx,cy-10,"18 in");s+=T(cx,H-12,"one stepping stone");return s+"</svg>"}const STOPS=[{id:1,title:"The Frame",short:"The Frame",parts:[{std:["RL.7.2"],dur:155,dir:"Read the story to yourself. Then answer out loud. Read me the lines you are relying on.",desc:"determining a theme and how it develops across a story, and giving an objective summary",html:()=>story(true),qs:["State a theme of this story in one sentence. A theme is a statement about people or about life, not a retelling of what happened.","Trace how that theme develops. Give three moments, in the order they appear, that move it along.","Early on the story says “the thing she wanted now, more than the hoop house, was to be the one who put it up.” How does the ending answer that sentence?","What do the two words she adds most likely say, and what evidence supports that?","Give an objective summary of the story in three or four sentences. Keep your own opinion of Dovie out of it."],key:["Any defensible statement about life, such as: doing a thing well is not the same as doing it alone; wanting the credit for something can get in the way of finishing it; sharing the work does not take the work away from you. Mark it down if the answer is a plot summary, such as “a girl builds a hoop house.” (RL.7.2, determining a theme)","Three moments in order, such as: she reads TWO PERSON JOB nine times and sets out to disprove it; three hours produce four ribs, the fifth goes in crooked, and the sixth bends, so the method is failing before anyone arrives; Selena holds the rib and says “It is a two person job,” and Dovie answers “Then hold the other end” by acting rather than agreeing; the six remaining ribs go in at about four minutes each, and Dovie “did that arithmetic on the walk home and did not enjoy it”; and the sign, which she changes herself. The order matters, because the theme is built by the gap between three hours and four minutes. (RL.7.2, development over the course of the text)","She gets exactly what that sentence names. The sign says DOVIE MARCHETTI, PROPOSAL AND BUILD, with no other name on it, and nobody takes it away from her. She changes it herself, in private, which means the wanting described in that sentence has been answered from the inside rather than corrected by somebody else. (RL.7.2)","Most likely “and Selena,” or Selena's name in some two-word form. Evidence: Selena is the only other person who worked on the build; the sign credits PROPOSAL AND BUILD and Selena did half the build; and the closing lines, “She did not tell anybody. Selena saw it in September,” only carry weight if what was added is about Selena. (RL.7.2, inference from the text)","An objective summary: Dovie plans and funds a hoop house and sets out to assemble the twelve-rib kit alone, although the box calls it a two person job. After three hours she has four ribs up, a fifth reset, and a sixth bent. Selena arrives without being asked, holds a rib, and the two of them finish the remaining six at about four minutes each. In June Dovie quietly adds two words to the sign that carries only her own name. Mark it down for praise, blame, or any word about what Dovie should have done. (RL.7.2, objective summary)"]}]},{id:2,title:"Set It Equal",short:"Equations",parts:[{title:"Equations",std:["7.EE.B.4"],dur:120,dir:"Work on your paper and hold it up. Write the equation before you solve it, and check your answer.",desc:"building and solving equations of the forms px + q = r and p(x + q) = r from word problems",html:()=>lead("Write the equation first. Say what your letter stands for before you use it."),qs:["The kit costs $348 and shipping costs $29. A grant pays $200 and the twelve students in the club split the rest evenly. Write and solve an equation for the amount a that each student pays.","Solve 3(x + 7) = 48.","The rectangular base of the hoop house has a perimeter of 72 feet and a width of 11 feet. Write and solve an equation for the length.","Solve −5x + 18 = 3.","Half of a number, decreased by 7, is 11. Write and solve an equation for the number."],key:["$14.75. The equation is 12a + 200 = 377, because 348 + 29 = 377. Then 12a = 177 and a = 14.75. Check: 12 × 14.75 + 200 = 177 + 200 = 377. Or: 377 − 200 = 177, then 177 ÷ 12, with the equation written too. Partial: $177 found with no share for each student is approaching. (7.EE.B.4a)","x = 9. Divide both sides by 3 to get x + 7 = 16, so x = 9. Expanding first gives 3x + 21 = 48, which lands in the same place. Check: 3(9 + 7) = 48. Partial: x = 16 leaves the 7 in and is approaching. (7.EE.B.4a)","25 feet. The equation is 2(L + 11) = 72, so L + 11 = 36 and L = 25. Check: 2(25 + 11) = 72. Or: half the perimeter is 36, and 36 − 11 = 25. Partial: 50 from taking 72 − 22 and not halving is approaching. (7.EE.B.4a)","x = 3. −5x = 3 − 18 = −15, so x = −15 ÷ −5 = 3. Check: −5(3) + 18 = 3. Or: add 5x to both sides, giving 18 = 5x + 3, so 5x = 15. (7.EE.B.4a)","36. The equation is n ÷ 2 − 7 = 11, so n ÷ 2 = 18 and n = 36. Check: 18 − 7 = 11. Partial: 18 given as the number is half of it and is approaching. (7.EE.B.4a)"]},{title:"Inequalities",std:["7.EE.B.4"],dur:100,dir:"Work on your paper and hold it up. Write what your letter stands for, solve, then say what the answer means for the real situation.",desc:"building and solving inequalities of the form px + q > r and interpreting the solution in context",qs:["One seed tray holds 18 cells. Next spring the club wants to raise at least 700 seedlings. Write and solve an inequality for the number of trays t, then say how many trays they actually need.","Solve 4x − 9 ≤ 23 and describe the solution in words.","Solve −3x + 5 > 20.","The club's separate repair fund holds $420. Each replacement rib costs $23 and the club has to leave at least $100 in that fund. Write and solve an inequality for the number of ribs n they can buy, then say how many that is.","Solve 2(n − 6) < 10 and describe the solution in words."],key:["39 trays. The inequality is 18t ≥ 700, so t ≥ 700 ÷ 18 = 38.88… You cannot buy part of a tray, so the answer in context is 39. Check: 38 trays give 684 cells, which is short, and 39 give 702. Partial: 38.88 or 38 given as the answer is approaching, since trays are whole and 38 falls short. (7.EE.B.4b)","x ≤ 8. In words: any number up to and including 8 works. Steps: 4x ≤ 32, so x ≤ 8. Partial: x ≤ 8 with no description in words is approaching. (7.EE.B.4b)","x < −5. Steps: −3x > 15, and dividing both sides by −3 flips the inequality, so x < −5. Answering x > −5 means the flip was missed. Partial: the inequality solved with the sign not flipped is approaching. (7.EE.B.4b)","13 ribs. The inequality is 420 − 23n ≥ 100, so −23n ≥ −320 and n ≤ 320 ÷ 23 = 13.91… They can buy 13. Check: 13 ribs cost $299 and leave $121, while 14 cost $322 and leave only $98. Or: 420 − 100 = 320 to spend, then 320 ÷ 23. Partial: 13.91 given as the answer is approaching. (7.EE.B.4b)","n < 11. In words: any number below 11, but not 11 itself. Steps: n − 6 < 5, so n < 11. Partial: n < 11 with no description in words is approaching. (7.EE.B.4b)"]}]},{id:3,title:"What the Packet Does Not Tell You",short:"Two Ideas",parts:[{std:["RI.7.2"],dur:155,dir:"Read the article to yourself. Then answer out loud. Read me the lines you are relying on.",desc:"determining two central ideas and how they develop, and giving an objective summary",html:()=>article(true),qs:["Name two central ideas of this article. State each one as a sentence.","Trace how the first central idea develops. What does the writer do after stating it?","How does the second central idea depend on the first?","The last two sentences are very short. What job do they do for the second central idea?","Give an objective summary of the article in three or four sentences."],key:["Two ideas, such as: the date printed on a seed packet does not tell you whether the seed will grow, because viability depends on the kind of seed and on how it was stored. And: you do not have to guess, because a simple germination test gives a number, and that number changes how thickly you sow rather than whether you sow at all. Any two defensible central ideas earn the check, as long as they are statements and not topics. (RI.7.2, two or more central ideas)","The writer states that the date is not a promise, then builds the case in two named parts: first the kind of seed, with onion and parsnip at two years against tomato, cucumber, and lettuce past five, and then storage, with the rule that temperature in Fahrenheit plus humidity in percent should stay under 100 and the garage example at 95 degrees. The hedge, “those are not rules, they are tendencies,” keeps the idea from becoming a new set of promises. (RI.7.2, development of a central idea)","The first idea creates the problem that the second answers. Once the date is not a promise and the two things that matter are the kind and the storage, the grower is left without a number, and the germination test supplies one. Without the first idea, the test would look like extra work. (RI.7.2, how the ideas develop together)","“A germination test is not a pass or a fail. It is a number you plant with.” They refuse the reading the writer expects, which is that a low result means the packet is spent, and they land the second idea in one phrase. Their shortness after four long paragraphs makes them the sentence the article wants kept. (RI.7.2)","An objective summary: seeds are alive and lose viability over time, and the date printed on a packet records only when the seed was packed. How long a seed lasts depends on its kind and on how it was stored, with a storage rule of temperature plus humidity staying under 100. A germination test of ten seeds on a damp towel gives the grower a percentage in about a week. The article argues that the result is not a verdict on the packet but a number that tells the grower how thickly to sow. Mark it down for opinion words or advice in the student's own voice. (RI.7.2, objective summary)"]}]},{id:4,title:"Work Out the Word",short:"Word Work",parts:[{title:"From the Sentence Around It",std:["L.7.4"],dur:85,dir:"Answer out loud. Say which words in the text helped you decide.",desc:"using context to work out unknown words, and choosing the right meaning of a multiple-meaning word",html:()=>lead("Every word below comes from one of the two texts. Use the sentences around it."),qs:["The article asks how long a seed stays <strong>viable</strong>. What does viable mean here, and which words nearby told you?","The article says, “Those are not rules, they are <strong>tendencies</strong>.” What does the contrast with rules tell you about tendencies?","In the story, the ribs go into ground <strong>sockets</strong>. A socket can also be an electrical outlet or part of the skull. Which meaning is in use here, and what do all three meanings share?","The story says Dovie would “<strong>sight</strong> down the pipe.” Sight is usually a noun. What does it mean as a verb here, and how did you decide?","The story is called “The Frame.” Give two different meanings of frame, and say which one the title is using."],key:["Able to live, or able to still sprout. The clues are in the first line, “a living thing in a paused state,” and in “the pause does not last forever,” plus the next sentences about seed going poor by the second year. (L.7.4a, context clues)","A tendency is what usually happens rather than what always happens, so it can have exceptions. The contrast is the clue, and the next clause narrows it further: “they are tendencies measured under good storage.” (L.7.4a, context clues)","A hollow fitting that the end of a pipe slides into and is held by. All three meanings name a hollow that something else sits in. The nearby words “into” and “set it again” point to the meaning in use. (L.7.4a, multiple-meaning words)","To look along something lengthwise to check whether it is straight. The clue is the next phrase, “the kind you only see if you sight down the pipe,” which is about how you look rather than about what you see. (L.7.4a, multiple-meaning words)","Two of: the structural skeleton of a building; a border around a picture or a window; to frame a question, meaning to set it up; to frame a person, meaning to make them look guilty. The title uses the first one, the structure of the hoop house, and may also be hearing the second, since the last scene is about a sign. (L.7.4a)"]},{title:"Roots and the Reference Shelf",std:["L.7.4"],dur:85,dir:"Answer out loud. For the last one, say exactly which part of the entry you would read.",desc:"using Greek and Latin roots and affixes, and using reference materials to check a meaning",qs:["The article uses germinates. The Latin root germen means sprout or bud. Use that to say what germination means.","Use the roots to explain annual, biennial, and perennial. The root ann means year, bi means two, and per means through.","A thermometer measures heat and a hygrometer measures humidity. Which part of each word is doing the measuring, and what do therm and hygro mean?","You decide that viable comes from a root meaning life. Which part of a dictionary entry would confirm that, and which part would tell you whether your meaning fits the sentence in the article?","You look up relative and find four numbered meanings. How do you work out which one is in use in “relative humidity”?"],key:["Germination is the process of a seed sprouting, the start of growth from the seed. The -ation ending turns the action into a noun. (L.7.4b, Greek and Latin roots)","An annual lives for one year. A biennial takes two years, usually growing the first year and flowering the second. A perennial lives on through the years and comes back. Needs the root used, not just the meaning recalled. (L.7.4b)","The ending -meter is doing the measuring, from the Greek for measure. Therm means heat and hygro means wet or moisture, so the words name what is being measured plus the measuring. (L.7.4b)","The etymology, which is the part in brackets or after the entry that gives the word's origin, would confirm the root. It comes from Latin vita, meaning life, by way of French. The numbered definitions, with their example sentences and the part of speech, would tell you whether the meaning fits the article's sentence. (L.7.4c and L.7.4d, using a reference and verifying)","Substitute each numbered meaning into the phrase and see which one still makes sense, then check the example sentences and any labels such as a science label. Here it is the meaning compared with something else, because relative humidity compares the moisture in the air with the most the air could hold at that temperature. (L.7.4c and L.7.4d, verifying a preliminary determination)"]}]},{id:5,title:"Can That Triangle Exist?",short:"Triangles",parts:[{std:["7.G.A.2"],dur:165,dir:"Use the two pictures. Answer out loud and say whether the conditions give exactly one triangle, more than one, or none. You can draw on your paper.",desc:"drawing shapes from given conditions and deciding when three measures give one triangle, many, or none",html:()=>lead("In each picture the base is drawn first. The dashed curve about each end shows every place the far end of that side could reach. A triangle exists only where the two curves meet."),fig:()=>`<div class="figure" style="gap:26px;align-items:flex-end;flex-wrap:wrap">${group(noTriFig(),"Picture 1: sides 4 cm, 6 cm, and 11 cm")}${group(triFig(),"Picture 2: sides 5 cm, 7 cm, and 9 cm")}</div>`,qs:["Picture 1. Can a triangle be made with sides of 4 cm, 6 cm, and 11 cm? Use the picture to explain.","Picture 2. Sides of 5 cm, 7 cm, and 9 cm. How many different triangles can be made?","A triangle has angles of 40°, 60°, and 80° and no side length is given. How many different triangles meet those conditions?","Two sides measure 6 cm and 8 cm and the angle between them is 50°. Exactly one triangle, more than one, or none?","Three angles measure 100°, 50°, and 40°. How many triangles meet those conditions?","Draw a quadrilateral with four right angles and sides of 5 cm and 8 cm. Is there more than one shape that fits?"],key:["No triangle. The two dashed curves never meet, because the short sides together reach only 4 + 6 = 10 cm while the base is 11 cm, so the far ends cannot touch. The rule: any two sides of a triangle have to add to more than the third. Partial: saying no with no comparison of 4 + 6 against 11 is approaching. (7.G.A.2, no triangle)","Exactly one. The two curves cross at a single point above the base, and the point below the base gives the same triangle flipped over, which is not a different triangle. Three given side lengths always fix one triangle, provided they satisfy the inequality: 5 + 7 = 12 is more than 9. Partial: exactly one with nothing said about the flip being the same triangle is approaching. (7.G.A.2, a unique triangle)","Infinitely many. The angles add to 180°, so triangles exist, but nothing fixes the size. Every one of them has the same shape and they differ only in scale. Partial: more than one with nothing said about size not being fixed is approaching. (7.G.A.2, more than one triangle)","Exactly one. Two sides with the angle between them fix the third vertex, so the third side and the other two angles follow. If the 50° angle were not between the two sides, that would not be true. Partial: exactly one with no reason that the third vertex is fixed is approaching. (7.G.A.2)","None. 100 + 50 + 40 = 190, and the three angles of a triangle have to add to exactly 180°. Partial: saying none with no total of the angles is approaching. (7.G.A.2, no triangle)","Only one shape: a 5 cm by 8 cm rectangle. Four right angles make it a rectangle, and the two given lengths fix both pairs of sides. Different placements or rotations on the paper are the same shape, not a different one. Partial: naming the rectangle with nothing said about rotations being the same shape is approaching. (7.G.A.2, drawing a shape from given conditions)"]}]},{id:6,title:"Beds and Boxes",short:"Area and Volume",parts:[{title:"Flat Shapes",std:["7.G.B.6"],dur:95,dir:"Use the two pictures. Work on your paper and hold it up. Say the unit every time.",desc:"area of two-dimensional figures made of rectangles, triangles, and trapezoids",html:()=>lead("Both beds below are drawn to the same scale. The dashed lines are heights and cut lines, not sides."),fig:()=>`<div class="figure" style="gap:26px;align-items:flex-end">${group(trapBed(),"Bed A")}${group(compBed(),"Bed B")}</div>`,qs:["The floor of the hoop house is a rectangle 11 feet by 25 feet. What is its area?","A path 2 feet wide runs the whole 25 foot length down the middle of that floor. How much floor is left for beds?","Bed A is a trapezoid with parallel sides of 9 feet and 5 feet and a height of 4 feet. What is its area?","Bed B is a 6 foot by 4 foot rectangle with a triangle on top of it. The triangle has a base of 6 feet and a height of 3 feet. What is the area of Bed B?"],key:["275 square feet. 11 × 25 = 275. (7.G.B.6)","225 square feet. The path is 2 × 25 = 50 square feet, and 275 − 50 = 225. Or: the two bed strips are 4.5 feet wide, so 2 × 4.5 × 25 = 225. Partial: 50 square feet for the path alone is approaching. (7.G.B.6)","28 square feet. (9 + 5) ÷ 2 = 7, and 7 × 4 = 28. Or: split it into a 5 by 4 rectangle, 20, and a triangle of ½ × 4 × 4 = 8. (7.G.B.6)","33 square feet. The rectangle is 6 × 4 = 24 and the triangle is 1/2 × 6 × 3 = 9, and 24 + 9 = 33. Or: enclose it in a 6 by 7 rectangle, 42, and take off the two corner triangles of 4.5 each. Partial: 24 for the rectangle alone, or 9 for the triangle alone, is approaching. (7.G.B.6, a composite figure)"]},{title:"Solid Shapes",std:["7.G.B.6"],dur:115,dir:"Work on your paper and hold it up. Say the unit every time, and say whether it is square or cubic.",desc:"volume and surface area of right prisms and composite solids in real-world problems",html:()=>lead("Volume fills a solid and is counted in cubic units. Surface area covers the outside and is counted in square units."),qs:["A raised bed box measures 8 feet by 3 feet by 1 foot deep. How much soil fills it?","Soil comes in bags of 1.5 cubic feet. How many bags fill that bed?","The compost bin is a cube 3 feet on each edge and it is open at the top. How much sheet material does it take to make the five faces?","Bed A from the last part has an area of 28 square feet. It is built as a right prism 0.75 feet deep. What is its volume?","A closed tool chest measures 4 feet by 2 feet by 1.5 feet. What is its surface area?"],key:["24 cubic feet. 8 × 3 × 1 = 24. Or: V = Bh with B = 24 square feet and h = 1 foot. (7.G.B.6, volume of a right prism)","16 bags. 24 ÷ 1.5 = 16. Or: two bags make 3 cubic feet, and 24 ÷ 3 = 8 pairs, so 16 bags. (7.G.B.6)","45 square feet. Each face is 3 × 3 = 9 square feet, and an open-topped cube has 5 faces, so 5 × 9 = 45. Answering 54 counts the lid that is not there. Partial: 9 square feet for one face right with the wrong number of faces is approaching. (7.G.B.6, surface area)","21 cubic feet. The volume of a right prism is the base area times the depth, so 28 × 0.75 = 21. Or: take three quarters of the base area, 28 × 3/4 = 21. (7.G.B.6, a prism with a trapezoid base)","34 square feet. The three pairs of faces are 4 × 2 = 8, 4 × 1.5 = 6, and 2 × 1.5 = 3, so 2 × (8 + 6 + 3) = 2 × 17 = 34. Or: work out all six faces one at a time and add. Partial: 17 for three faces only is approaching. (7.G.B.6, surface area of a closed box)"]}]},{id:7,title:"Put the Modifier Where It Belongs",short:"Grammar",parts:[{title:"One Mistake Each",std:["L.7.1"],dur:85,dir:"Each line has one modifier in the wrong place or with nothing to attach to. Say the whole line out loud the right way.",desc:"recognizing and correcting misplaced and dangling modifiers",qs:["Sighting down the pipe, the flat spot was easy to see.","Dovie only seated four ribs in three hours.","Mr. Abara made a sign for the hoop house with a marker.","Dovie found a marker in the shed that was almost dry.","Having read the box nine times, the line still bothered her."],key:["Any fix that gives the phrase a doer, such as “Sighting down the pipe, Dovie could see the flat spot easily,” or “The flat spot was easy to see if you sighted down the pipe.” As written the participial phrase dangles, because a flat spot cannot sight down anything. (L.7.1c, dangling modifier)","Dovie seated only four ribs in three hours. Placed before seated, only limits the seating; placed before four, it limits the number, which is the meaning the sentence wants. (L.7.1c, misplaced modifier)","With a marker, Mr. Abara made a sign for the hoop house. As written, the phrase sits beside the hoop house, so it reads as though the hoop house has the marker. (L.7.1c, misplaced phrase)","In the shed, Dovie found a marker that was almost dry. As written, the relative clause sits beside the shed, so it reads as though the shed was almost dry. (L.7.1c, misplaced clause)","Any fix that gives the phrase a doer, such as “Having read the box nine times, she was still bothered by the line.” A line cannot read the box. (L.7.1c, dangling modifier)"]},{title:"Build the Sentence",std:["L.7.1"],dur:65,dir:"Answer out loud. Say whole sentences when you build one.",desc:"the function of phrases and clauses, and choosing among sentence types to signal a relationship",qs:["Name the kind of sentence and say what its structure signals: Dovie read the line, but she did not believe it.","Combine these into one complex sentence using a subordinate clause: Selena did not ask. She picked up the seventh rib.","Name the kind of sentence: Although the box said four hours, Dovie worked for three, and she got only four ribs in.","In “It took on a slight flat spot about a third of the way up,” what job does the phrase “about a third of the way up” do in the sentence?"],key:["Compound. Two independent clauses joined by the coordinating conjunction but, which signals that the two ideas carry equal weight and that the second one works against the first. (L.7.1b, sentence types and the relationships they signal)","Any correct version built on a subordinate clause, such as “Because Selena did not ask, she simply picked up the seventh rib,” or “Selena picked up the seventh rib before she had asked anything.” A version joined with and is compound, not complex, and does not earn the check. (L.7.1b)","Compound-complex. It has a subordinate clause, “Although the box said four hours,” and two independent clauses joined by and. (L.7.1b)","It is a prepositional phrase working as a modifier. It tells where on the pipe the flat spot is, which is what makes the damage hard to see and worth sighting along. (L.7.1a, the function of phrases in a sentence)"]}]},{id:8,title:"Speak to the Site Council",short:"Present",parts:[{std:["SL.7.4"],n:5,label:"checks met",dur:145,dir:"Plan for 1 minute. Then speak for 1 to 2 minutes. Look at the camera, speak up, and say your words clearly.",desc:"a 1 to 2 minute spoken presentation of a claim and findings, with pertinent facts, details, and examples",html:()=>lead("The site council is deciding whether the hoop house stays student-run or is handed to the facilities department. You have two minutes.")+bigTable(["","Student-run, as it is now","Handed to facilities"],[["Cost to the school district","$0 so far. The $377 kit came from a $200 grant and $14.75 from each of twelve students.","About $2,900 a year for one staff hour a week plus supplies."],["Who opens the roof vent","Whoever has the morning shift","A staff member on a scheduled round"],["Days above 85 °F when the vent was not opened","7","0 expected"],["Seedlings raised and given to the community garden this spring","620","Not yet estimated"],["Student hours logged","310","0"],["Trays the house holds","41","41"]],"The hoop house, first year")+`<p class="big" style="font-size:1.48rem">State your claim, give your two strongest findings, name an example that makes one of them concrete, say honestly what the other side has going for it, and end with what you want the council to do.</p><div class="row center" style="margin-top:14px;gap:12px">${["My claim","Finding 1","Finding 2","A concrete example","What the other side has","What I am asking for"].map(x=>`<span class="pill" style="font-size:1.06rem">${x}</span>`).join("")}</div>`,key:["States one clear claim at the start and keeps the whole talk pointed at it. Either side can be argued. The student-run case rests on $0 against $2,900, on 310 student hours, and on 620 seedlings. The facilities case rests on the 7 days above 85 degrees when nobody opened the vent. (SL.7.4, presenting a claim)","Emphasizes the salient points in a focused, coherent order rather than reading the table across (SL.7.4)","Uses pertinent facts and details from the table, stated accurately. A changed number does not count. (SL.7.4)","Gives at least one concrete example or description that makes a finding real rather than numerical, such as what happens inside a closed hoop house on a day above 85 degrees, or what 620 seedlings looks like leaving the building. (SL.7.4, pertinent descriptions and examples)","Appropriate eye contact with the camera, adequate volume, and clear pronunciation for 1 to 2 minutes (SL.7.4)"]}]},{id:9,title:"Field Desk",short:"Write",parts:[{alt:{group:"write",key:"argument",label:"Argue",icon:"⚖️",hint:"Student-run, or handed to facilities?"},std:["W.7.1"],n:6,label:"checks met",dur:220,dir:WRITE_DIR,desc:"an argument writing piece built from a fact box",html:()=>`<p class="big">The site council has to choose one. Write an argument telling it which to pick. Use the fact box. Write 8 to 10 sentences.</p>${factBox("Fact box: the hoop house, first year",["<strong>Student-run, as it is now.</strong> Cost to the district so far: $0. The $377 kit came from a $200 grant and $14.75 from each of the twelve club members. Students logged 310 hours and raised 620 seedlings for the community garden.","<strong>Handed to facilities.</strong> About $2,900 a year for one staff hour a week plus supplies. A staff member would open the roof vent on a scheduled round.","On 7 days above 85 degrees Fahrenheit this spring, nobody opened the roof vent.","The house holds 41 trays. Nothing about the building itself changes either way.","Two club members graduate in June. Four have signed up for next year."])}${checklist(["Introduce your claim, acknowledge the other side, and organize the reasons clearly","Support the claim with logical reasoning and relevant evidence from the fact box, used accurately","Use words, phrases, and clauses that show how your claim, reasons, and evidence connect","Keep a formal style, with no slang and no jokes to the reader","End with a conclusion that follows from and supports your argument"])}`,key:["Introduces the claim, acknowledges the opposing claim, and organizes the reasons and evidence logically (W.7.1a)","Supports the claim with logical reasoning and relevant evidence from the fact box, such as $0 against $2,900, or the 7 unopened days (W.7.1b)","Shows understanding of the topic by using the numbers accurately rather than inventing them (W.7.1b)","Uses words, phrases, and clauses to create cohesion and to clarify the relationships among the claim, the reasons, the evidence, and the counterclaim (W.7.1c)","Establishes and maintains a formal style (W.7.1d)","Ends with a concluding statement that follows from and supports the argument (W.7.1e)"]},{alt:{group:"write",key:"facts",label:"Explain",icon:"📘",hint:"How to test old seed"},std:["W.7.2"],n:6,label:"checks met",dur:220,dir:WRITE_DIR,desc:"an informative writing piece",html:()=>`<p class="big">Write to explain to a first-year gardener what the date on a seed packet does and does not tell them, and what to do instead. Use facts from the article. Write 8 to 10 sentences.</p>${checklist(["Introduce the topic clearly and preview what is coming","Organize the ideas into clear parts, with a paragraph break where the subject turns","Develop the topic with facts, definitions, concrete details, and at least one number from the article","Use transitions to show how the parts connect","Use precise language and the vocabulary the subject needs","Keep a formal style and end with a conclusion that follows from the information"])}${`<details class="look-back" open><summary>Look back at the article</summary>${article(true)}</details>`}`,key:["Introduces the topic clearly, previews what is coming, and organizes the ideas into clear parts (W.7.2a)","Develops the topic with facts, definitions, concrete details, and at least one number used accurately, such as the under-100 storage rule, two years for onion, five for tomato, or ten seeds in the test (W.7.2b)","Uses appropriate transitions to create cohesion and clarify the relationships among the ideas (W.7.2c)","Uses precise language and domain-specific vocabulary such as viable, germination rate, or relative humidity, and explains what they mean (W.7.2d)","Establishes and maintains a formal style (W.7.2e)","Ends with a concluding statement that follows from and supports the information presented (W.7.2f)"]},{alt:{group:"write",key:"narrative",label:"Story",icon:"🌱",hint:"The job that said TWO PERSON JOB"},std:["W.7.3"],n:6,label:"checks met",dur:220,dir:WRITE_DIR,desc:"a narrative writing piece",html:()=>`<p class="big">You have set out to finish something by yourself, on purpose, and partway through it becomes clear that you are not going to. Somebody shows up who could help. Write the story of the next hour. Write 10 to 12 sentences.</p>${checklist(["Set up the situation and the point of view, and introduce the narrator and the other person","Tell the events in an order that unfolds naturally","Use dialogue and pacing to show how the two of them handle the moment","Use transition words and phrases to signal shifts in time","Use precise words, relevant descriptive details, and sensory language","End with a conclusion that follows from and reflects on the events"])}`,key:["Engages and orients the reader by establishing a context and point of view and introducing a narrator and characters (W.7.3a)","Organizes an event sequence that unfolds naturally and logically (W.7.3a)","Uses narrative techniques such as dialogue, pacing, and description to develop the events and the characters (W.7.3b)","Uses transition words, phrases, and clauses to convey sequence and to signal shifts from one time frame or setting to another (W.7.3c)","Uses precise words and phrases, relevant descriptive details, and sensory language to capture the action (W.7.3d)","Provides a conclusion that follows from and reflects on the narrated experiences or events (W.7.3e)"]}]},{id:10,title:"Two Views of One Build",short:"Two Views",parts:[{title:"Who Is Telling It",std:["RL.7.6"],n:3,dur:50,dir:"Look back at the story. Answer out loud.",desc:"analyzing how an author develops and contrasts the points of view of two characters",html:()=>`<details class="look-back" open><summary>Look back at the story</summary>${story(true)}</details>`,qs:["Whose point of view does the narration follow? Point to the evidence.","Selena says only three short things. From those lines, what is her view of the job, and how does it contrast with Dovie's?","The author never tells us the two words Dovie added to the sign. How does holding that back serve the contrast between the two of them?"],key:["Dovie's. The narration reports her thoughts and nobody else's: she read the line about nine times, what she wanted now was to be the one who put it up, the method with her knee she would not have described to anyone, the arithmetic she did on the walk home and did not enjoy. Selena's inner life is never reported, only her words and what she does (RL.7.6)","Selena treats it as a job that takes two people and says so flatly, quoting the box back. She does not ask whether she is wanted and she makes no claim on the credit: Then hold the other end. Dovie's view is that doing it alone is the point, which is why the sign matters to her. The contrast is between the work and the ownership of the work (RL.7.6)","It keeps Dovie from announcing the change, which is in character for someone who did not tell anybody. The reader can work out what the two words are, but the story stays inside Dovie's view and lets Selena find out in September, so even at the end the two points of view are held apart by a silence (RL.7.6)"]},{title:"The Story and the Record",std:["RL.7.9"],n:3,dur:50,dir:"Read the build log. Then compare it with the story. Answer out loud.",desc:"comparing a fictional account and a factual record of the same events",html:()=>`${buildLog()}<details class="look-back" open><summary>Look back at the story</summary>${story(true)}</details>`,qs:["Name two things the story includes that the log leaves out, and say why a log leaves them out.","The log gives rib 6 one line. The story gives it most of a page. What does the fiction do with that fact that the record does not?","Does the story contradict the log anywhere, or does it do something else? Use both texts to answer."],key:["Any two of: why Dovie wanted to build it alone, what the line on the box did to her, the method with her knee, how long she sat sighting down the bent pipe, the dialogue with Selena, the sign and the two added words. A log is kept to record what happened and what it cost, for a grant report, so it records actions, times and money and leaves out motive and feeling (RL.7.9)","The log treats the flat spot as a supply problem: no spare rib, note it for the report. The story turns the same pipe into the moment the plan stops working, and uses Dovie sitting on the grass sighting down it to show her deciding something about herself rather than about the pipe (RL.7.9)","It does not contradict it. Every hard fact lines up: alone at her own request, four ribs by about midday, rib 5 reset, rib 6 flat and not replaced, Selena at four, the last six in before five thirty, $0 to the district. What the author does is fill the silences in the record with motive, dialogue and an ending the log has no room for. Count it correct when the student names at least two facts that match and then says the invention is in the gaps (RL.7.9)"]}]},{id:11,title:"Two Letters to the Council",short:"Two Letters",parts:[{title:"Does the Argument Hold",std:["RI.7.8"],n:3,dur:50,dir:"Read both letters. Then answer about Source Q.",desc:"tracing an argument and judging whether its reasoning is sound and its evidence sufficient",html:()=>twoLetters(),qs:["What is Dale Okafor's claim, and what reasons does the letter give for it?","Which of the evidence is relevant to the claim, and where is the evidence not enough?","Judge this move: Every program run by students has gaps. Ours has them too. Is that sound reasoning?"],key:["The claim is that the hoop house should stay student-run. The reasons given are that it produced 620 seedlings, more than any purchased source has supplied; that it cost the district nothing, with the $377 kit covered by a $200 grant and twelve students at $14.75; and that the students did the proposal, the measuring and the build (RI.7.8)","The cost figures and the 620 seedlings are relevant and accurate, and they do support the claim that the program is cheap and productive. They are not sufficient against the objection actually raised, which is about the seven warm days. Nothing in the letter is evidence about whether a tray was harmed or whether the gap can be closed, so the claim that the gaps do not matter is unsupported (RI.7.8)","It is weak. It concedes that the gaps exist and then treats that concession as a defense, which it is not: that other programs also have gaps says nothing about whether this one's gaps are acceptable. Count it correct when the student names the move, not only dislikes it. A student who says it is reasonable has to explain why a shared weakness would excuse this one (RI.7.8)"]},{title:"Same Facts, Two Shapes",std:["RI.7.9"],n:3,dur:45,dir:"Use both letters. Answer out loud.",desc:"analyzing how two authors on one topic emphasize different evidence and read the same facts differently",html:()=>twoLetters(),qs:["Both writers had the same facts. Name one fact each writer leans on that the other leaves out or plays down.","Both mention the seven warm days. How does each one interpret that same fact?","How does who each writer is shape what counts as evidence to them?"],key:["Brandt leans on the seven days above 85 degrees and on the two members graduating, and she never mentions the 620 seedlings or the $0 cost. Okafor leans on the 620 seedlings and the $0 cost, and gives the seven days one dismissive clause. Both use the 310 hours and the $2,900, and they read them in opposite directions (RI.7.9)","Brandt reads them as evidence of a coverage gap and makes them worse with a what-if about a Saturday. Okafor reads them as a side issue and reframes the whole question as what $2,900 buys. The number is identical in both letters; the interpretation is the difference (RI.7.9)","Brandt is a heating and cooling technician, so equipment and scheduled coverage are what she treats as evidence, and a near miss counts to her. Okafor runs the community garden, so output and cost are what he treats as evidence, and he counts what arrived rather than what might have gone wrong (RI.7.9)"]}]},{id:12,title:"Source Desk",short:"Sources",parts:[{std:["W.7.8"],n:3,label:"checks met",dur:50,dir:"Use both letters. Write your answers on your paper and hold them up.",desc:"choosing search terms, judging the credibility of sources, and quoting and paraphrasing with a citation",html:()=>`${twoLetters()}<p class="big" style="font-size:1.42rem">Research question: how hot does a closed hoop house get on a spring day, and how hot is too hot for a tray of seedlings?</p>`,qs:["Write two search terms you would use for that question, and say why each is better than typing hoop house hot.","On the temperature question, which letter is the more credible source, and why? Name one thing that would make you trust the other one more.","Quote one sentence from Source P with a citation. Then paraphrase the same sentence without using its wording."],key:["Any two terms that narrow the question, such as hoop house interior temperature spring, unvented greenhouse heat buildup, or seedling heat stress temperature threshold. They are better because each one names the measurement wanted and the condition it is wanted under, while hoop house hot gives the engine no quantity, no condition and no units (W.7.8, using search terms effectively)","Source P. Brandt is a licensed heating and cooling technician, so the question is inside her field, and she gives a number with a condition attached: seven days past 85 degrees with the vent shut. Okafor coordinates the community garden, which makes him credible about seedling output and not about interior temperature. What would raise trust in either letter is a stated source for the readings: who logged the temperature, with what instrument, where in the house it sat (W.7.8, assessing credibility)","A quotation copied exactly, inside quotation marks, with a citation naming the author and the source, such as: Brandt, Ileana. Letter to the site council. A paraphrase of the same sentence in the student's own sentence structure, with the meaning kept and no phrase longer than a couple of words carried over. Both are needed for this check (W.7.8, quoting and paraphrasing without plagiarism)"]}]},{id:13,title:"Trays and Seedlings",short:"Proportional",parts:[{std:["7.RP.A.2"],n:3,dur:45,dir:"Look at the two tables. Work on your paper. Say your answers out loud.",desc:"deciding whether a relationship is proportional, naming the constant, and writing the equation",html:()=>lead("The club counts its seedlings by the tray."),fig:()=>group(bigTable(["Trays","Seedlings"],[["2","40"],["5","100"],["8","160"],["12","240"]]),"Table 1: the hoop house"),fig2:()=>group(bigTable(["Trays","Seedlings"],[["3","70"],["6","130"],["9","190"]]),"Table 2: the outdoor bed"),qs:["Is Table 1 a proportional relationship? How can you tell from the table alone?","What is the constant of proportionality, what does it mean here, and what is the equation?","Is Table 2 proportional? Show why or why not."],key:["Yes. Every pair gives the same ratio of seedlings to trays: 40/2 = 20, 100/5 = 20, 160/8 = 20, 240/12 = 20. Equal ratios in every row is the test. Or: graph the pairs and see a straight line through the origin. Partial: one ratio checked only is approaching.","20, which is 20 seedlings per tray. The equation is s = 20t, where t is trays and s is seedlings. On a graph it would be a straight line through the origin, and the point (1, 20) is the constant. Partial: two of the three parts answered is approaching.","No. 70/3 is about 23.3 while 130/6 is about 21.7 and 190/9 is about 21.1. The ratios are not equal, so there is no single constant and no equation of the form s = kt fits all three rows. Or: cross multiply to test 70/3 against 130/6, 420 against 390, which are not equal."]}]},{id:14,title:"Discount, Tax, Takings",short:"Percent",parts:[{std:["7.RP.A.3"],n:3,dur:50,dir:"Work each one on your paper. Say your answer out loud.",desc:"multistep percent problems: a discount with tax on top, a percent increase, and a percent of an amount",html:()=>lead("The club is pricing a second kit and working out what to keep back for next year's seed."),qs:["A second kit is listed at $420. The supplier takes 15% off for schools, and then 8.25% sales tax is added to the discounted price. What is the final price?","The first kit cost $377 and this one is listed at $420. What is the percent increase in the list price?","Next spring the club plans to raise 620 seedlings again and sell that batch for 50 cents each, keeping 20% of the takings for seed. How much is kept?"],key:["$386.45. The discount leaves 85%: 420 x 0.85 = $357. Tax adds 8.25%: 357 x 1.0825 = $386.4525, which is $386.45 to the cent. Taking the tax off the $420 first is the common mistake. Or: 420 × 0.85 × 1.0825 in one chain. Partial: $357 found with no tax added is approaching.","About 11.4%. The change is 420 - 377 = $43, and the increase is measured against the original: 43 / 377 = 0.1141 to four places, which is 11.4% rounded to one. Dividing by 420 instead gives 10.2% and is wrong. Or: 420 ÷ 377 = 1.114, so the new price is about 111.4% of the old.","$62. The takings are 620 x $0.50 = $310, and 20% of $310 is 0.20 x 310 = $62. Or: 20% of 50 cents is 10 cents a seedling, and 620 × 0.10 = 62. Partial: $310 found with no 20% taken is approaching."]}]},{id:15,title:"The Club Account",short:"The Account",parts:[{std:["7.NS.A.3","7.EE.B.3"],n:3,dur:55,dir:"Work on your paper. Say your answers out loud.",desc:"operating with positive and negative rational numbers and checking the result with an estimate",html:()=>lead("The club account opened the spring at negative $42.50, because the supplier had not been paid. Then twelve members each paid in $14.75. The club spent $86.20 on potting mix and $31.75 on seed."),qs:["What is the balance at the end?","One member asks for 2/5 of their $14.75 back. How much is that, and what is the balance after it is paid?","Before you worked the first one out exactly, what estimate would you have made in your head, and does the exact answer look reasonable against it?"],key:["$16.55 (7.NS.A.3). The twelve payments are 12 x 14.75 = $177.00. Then -42.50 + 177.00 = 134.50, 134.50 - 86.20 = 48.30, and 48.30 - 31.75 = 16.55. Or: total the three payments out, 42.50 + 86.20 + 31.75 = 160.45, then 177 − 160.45 = 16.55.","$5.90, and the balance becomes $10.65 (7.NS.A.3). Two fifths of 14.75 is 14.75 x 2 = 29.50 divided by 5, which is 5.90. Then 16.55 - 5.90 = 10.65. Converting the fraction to a decimal is fine, and so is 0.4 x 14.75. Partial: $5.90 found with no new balance is approaching.","Roughly: negative 40 plus 180 is 140, take off about 86 to get a bit over 50, take off about 32 to get about 20 (7.EE.B.3). $16.55 is close to $20, so the exact answer is reasonable. Any clear estimate in the $10 to $25 range counts. Listen for the student comparing the estimate with the answer, not just producing an estimate. Partial: an estimate given with no comparison to the exact answer is approaching."]}]},{id:16,title:"Round the Stepping Stone",short:"Circles",parts:[{std:["7.G.B.4"],n:3,dur:50,dir:"Use 3.14 for pi. Work on your paper. Say your answers out loud.",desc:"circumference and area of a circle, and an informal account of how the two are related",html:()=>lead("The path into the hoop house is laid with round stepping stones."),fig:()=>circleFig(),qs:["A stepping stone is 18 inches across. Find its circumference and its area.","A round bed has a circumference of 31.4 feet. What is its radius, and what is its area?","Give an informal reason why the area of a circle comes out as half the circumference times the radius."],key:["Circumference about 56.52 inches, since C = pi x d = 3.14 x 18. Area about 254.34 square inches, since the radius is 9 and A = pi x r squared = 3.14 x 81. Using the diameter in the area formula gives 1017.36 and is the usual error. Partial: one of the circumference and the area right is approaching.","Radius 5 feet, since C = 2 x pi x r gives 31.4 = 6.28r. Area 78.5 square feet, since 3.14 x 25 = 78.5. Partial: the radius right with no area given is approaching.","Cut the circle into a lot of thin wedges and lay them out alternately point up and point down. They form a shape close to a rectangle. Its long side is made of half the arcs, so it is half the circumference, which is pi x r. Its short side is the radius. So the area is about pi x r x r, that is pi r squared. The thinner the wedges, the closer the shape gets to a rectangle. Partial: naming the rectangle with no account of which side is half the circumference is approaching."]}]},{id:17,title:"Inside and Outside",short:"Two Samples",parts:[{std:["7.SP.B.4"],n:3,dur:50,dir:"Work on your paper. Say your answers out loud.",desc:"comparing two random samples by center and variability and drawing an informal inference about the populations",html:()=>lead("The club measured a random sample of ten seedlings from the hoop house and a random sample of ten from the outdoor bed. Heights are in centimeters."),fig:()=>group(bigTable(["Sample","Heights in cm"],[["Hoop house","9, 10, 10, 11, 12, 12, 13, 13, 14, 16"],["Outdoor bed","6, 7, 7, 8, 8, 9, 10, 10, 12, 13"]]),"Ten seedlings from each"),qs:["Find the mean and the median of each sample.","Find the mean absolute deviation of each sample.","Draw an informal comparative inference about the two populations. How big is the difference between the centers compared with the variability?"],key:["Hoop house: total 120, so the mean is 12.0 cm, and the median is 12 cm, the average of the fifth and sixth values. Outdoor bed: total 90, so the mean is 9.0 cm, and the median is 8.5 cm, the average of 8 and 9. Partial: the means right with the medians missing, or the reverse, is approaching.","Hoop house 1.6 cm: the distances from 12 are 3, 2, 2, 1, 0, 0, 1, 1, 2, 4, which total 16, and 16/10 = 1.6. Outdoor bed 1.8 cm: the distances from 9 are 3, 2, 2, 1, 1, 0, 1, 1, 3, 4, which total 18, and 18/10 = 1.8. Partial: one of the two mean absolute deviations right is approaching.","Hoop house seedlings are generally taller. The means differ by 3.0 cm, which is close to twice the mean absolute deviation of either sample, so the gap between the groups is large next to the spread inside each group. Because both are random samples, that supports an inference about the two populations and not only about the twenty plants measured. A student who compares the centers and ignores the spread has done half of it. Partial: comparing the centers and ignoring the spread is approaching."]}]},{id:18,title:"Who Does What",short:"Chances",parts:[{std:["7.SP.C.8"],n:3,dur:50,dir:"Work on your paper. Say your answers out loud.",desc:"finding probabilities of compound events with an organized list or table",html:()=>lead("Each Saturday the morning job is settled by two fair draws. One draw picks the task from water, vent and log. The other picks the shift, early or late. The two draws do not affect each other."),qs:["List every possible outcome in an organized list or a table. How many are there?","What is the probability of drawing vent and early?","What is the probability of drawing the vent task on at least one of two Saturdays?"],key:["6 outcomes: water-early, water-late, vent-early, vent-late, log-early, log-late. A 3 by 2 table or a tree with 3 branches then 2 branches each both count. The count has to be organized, not a scatter of guesses. Or: 3 × 2 = 6 by multiplying the choices, as long as the list or table is there too.","1/6. The two draws are independent, so 1/3 x 1/2 = 1/6. It is also 1 of the 6 equally likely outcomes in the list. Partial: 1/3 or 1/2 given alone is approaching.","5/9. The chance of not drawing vent on one Saturday is 2/3, so the chance of missing it both times is 2/3 x 2/3 = 4/9, and 1 - 4/9 = 5/9. Adding 1/3 + 1/3 to get 2/3 double counts the Saturdays on which vent comes up twice. Or: add the cases, 4/9 for vent on exactly one Saturday plus 1/9 for both, which is 5/9."]}]},{id:19,title:"Smaller Towns, Fewer Ships",short:"Smaller Towns",parts:[{std:["HSS-7.1"],n:4,dur:100,dir:"Look at the chart. Answer out loud.",desc:"analyzing the contraction of cities, trade and coinage in the west after the empire ended",html:()=>`<p class="big">What happened in the western Mediterranean in the two centuries after the western empire stopped governing.</p>
     <table class="bigTable"><tr><th>What historians measure</th><th>What it shows</th></tr>
     <tr><td>the size of towns, from their walls and the ground built on</td><td>most shrank sharply; some were abandoned; new walls enclosed a fraction of the old area</td></tr>
     <tr><td>pottery found at dig sites</td><td>mass produced wares shipped from one end of the sea to the other give way to rough local pots</td></tr>
     <tr><td>coins found in ordinary settlements</td><td>far fewer, and small change almost disappears</td></tr>
     <tr><td>bones and teeth from burials</td><td>a diet with less variety, and more of it grown nearby</td></tr></table>
     <div class="figure">${ico("box",74)}${ico("coin",74)}${ico("wheat",74)}</div>`,qs:["Pottery shipped across the sea is replaced by rough local pots. Explain what that single change tells you about the economy.","Small change almost disappears from ordinary settlements. Explain what people would be doing instead, and what that means for daily life.","Towns shrank but did not all vanish. Name one reason some kept going, even much smaller.","Historians use pots, coins and bones rather than written accounts for this period. Explain why."],key:["That long distance trade in ordinary goods had stopped. Mass produced pottery only travels when there is regular, cheap shipping, a market that can pay, and peace enough to carry low value cargo a long way. Rough local pots mean each district is making what it needs, which is a far poorer and far more local economy. Partial: noting the rough pots with nothing said about what that means for trade is approaching. (HSS-7.1)","Barter, exchange in kind, and payment in grain, cloth or labor. Small coins exist for buying bread and small goods in a market, so their disappearance means people are not often buying small things from strangers for money. Daily life becomes a matter of what your household and your neighbors produce rather than what you can buy. Partial: naming barter with nothing said about what small coins were for is approaching. (HSS-7.1)","Any one: a bishop’s seat kept administration, records and a reason for people to come; a defensible site kept its use; a place on a river crossing or a surviving road still had traffic; and a ruler or a landholder needed a center. Towns that had a function other than trade had a reason to continue. Partial: naming a town with no function other than trade named is approaching. (HSS-7.1)","Because very little was written in the west in this period, and what was written was by a few clergy with their own purposes and often about other things. Pots, coins and bones were not written to persuade anyone, they survive in large numbers, and they can be counted and compared from site to site, so they answer questions about ordinary life that no surviving text answers. Partial: saying there are few documents with nothing said about why objects answer different questions is approaching. (HSS-7.1)"]},{std:["HSS-7.6"],n:3,dur:90,dir:"Read the note. Answer out loud.",desc:"analyzing the labor shortage after the plague and its effect on wages, land and obligations",html:()=>`<p class="big">Plague reached Europe in 1347 and returned in waves. Historians estimate that it reduced the population by something between a third and a half within a few years. The land, the buildings, the tools and the animals were all still there, and far fewer people were left to work them. Wages for laborers rose, rents fell, poor land went out of cultivation, and some landlords turned arable fields over to sheep because sheep need fewer hands. Several governments passed laws fixing wages at the old levels and forbidding workers to move for better pay. Those laws were widely broken, and attempts to enforce them were among the causes of large revolts.</p>
     <div class="figure">${ico("sheep",74)}${ico("wheat",74)}${ico("coin",74)}</div>`,qs:["The land and tools were unchanged and the workers were far fewer. Explain, in terms of supply and demand, why wages rose and rents fell.","Governments passed laws fixing wages at the old levels. Explain why those laws were so hard to enforce.","Name one lasting change this period brought to the obligations a tenant owed a lord."],key:["Labor had become scarce relative to land, so whoever could work could ask more for it, and employers competing for a small number of hands bid the price up. Land had become plentiful relative to the people who wanted to farm it, so a landlord competing for tenants had to lower the rent or leave the field empty. The price of each moved with how scarce it had become. Partial: one of the two prices explained is approaching. (HSS-7.6)","Because every individual employer had a strong reason to break them: paying a little over the limit got the harvest in, and refusing meant losing the worker to a neighbor who would pay. Enforcement depended on the same landowners who wanted the labor, workers could simply move, and there were not enough officials to police thousands of private bargains. A law against a price that everyone wants to pay is very hard to hold. Partial: saying nobody obeyed with no account of why each employer had reason to break it is approaching. (HSS-7.6)","Any one: labor services owed in days of work were increasingly commuted into money rents, which turned a tenant into something nearer a renter; serfdom weakened and in places faded out in western Europe, because a lord who could not keep tenants could not enforce old dues; and leases and written agreements spread, since both sides now wanted terms fixed. Partial: naming a change with no link to the shift in bargaining power is approaching. (HSS-7.6)"]}]},{id:20,title:"Streets, Salt and Steppe Roads",short:"Streets",parts:[{std:["HSS-7.2"],n:3,dur:90,dir:"Read the note. Answer out loud.",desc:"analyzing the layout and public institutions of a medieval Islamic city",html:()=>`<p class="big">A large city such as Fez, Aleppo or Isfahan was arranged around the Friday mosque, where the whole community gathered once a week. Beside it lay the main covered market, with trades grouped street by street: booksellers and perfumers nearest the mosque, dyers and tanners at the edge because of the smell and the water they used. Nearby stood a madrasa, a college where law and religious subjects were taught and students were housed, and a public bath, and a fountain or cistern, and a caravanserai where traveling merchants and their animals could stay. Nearly all of these were paid for by waqf endowments rather than by the city government. The residential quarters behind them were reached by lanes that often ended in a dead end.</p>
     <div class="figure">${ico("lantern",74)}${ico("drop",74)}${ico("books",74)}</div>`,qs:["Booksellers next to the mosque and tanners out at the edge. Explain the thinking behind where each trade was put.","A college, a bath, a fountain and an inn for travellers, all paid for by endowments. Explain what that tells you about how public provision worked in these cities.","The lanes into the residential quarters often ended in a dead end. Name one thing that arrangement provided for the people who lived there."],key:["Trades that serve people coming to the mosque, and that are clean and quiet, belong next to it; the booksellers also sold what the students and scholars needed. Tanning and dyeing smell strongly, need a great deal of water and pour out waste, so they were put downstream and downwind at the edge where they would not spoil the center. The layout follows what each trade does to its neighbors. Partial: one of the two groups of trades explained is approaching. (HSS-7.2)","That it rested on religious obligation and private giving rather than on taxation. A wealthy founder gained standing and acted on a duty to give; the endowment then paid for the service permanently and could not be seized. It also means the services clustered where founders wanted to be seen giving, and that a city’s provision depended on there being wealthy donors. Partial: naming the endowments with nothing said about provision depending on donors is approaching. (HSS-7.2)","Any one: privacy, since a dead end lane carries only the traffic of the families living on it; a known neighborhood, where a stranger is noticed; safety, because it can be closed off; and a quiet space for households whose life was turned inward toward a courtyard rather than outward to the street. Partial: describing the lanes with no advantage to the households named is approaching. (HSS-7.2)"]},{std:["HSS-7.4"],n:3,dur:90,dir:"Read the note. Answer out loud.",desc:"analyzing the salt mines of the Sahara and the economics of a necessary good",html:()=>`<p class="big">Taghaza, in the middle of the Sahara, sat on a bed of rock salt. There was no farmland, no pasture and almost no fresh water. Workers cut the salt into slabs about the size of a door and loaded them onto camels, two to a camel. Everything they ate and drank was carried in from hundreds of miles away, which made Taghaza one of the most expensive places in the world to live and one of the most valuable to own. A traveller in the 1350s wrote that the houses there were built of salt slabs roofed with camel skins. Further south the same slabs were worth a great deal more, and in some markets salt was traded against gold by weight.</p>
     <div class="figure">${ico("box",74)}${ico("sun",74)}${ico("moneybag",74)}</div>`,qs:["Everything the workers consumed had to be carried hundreds of miles. Explain why anyone would mine salt in such a place anyway.","The same slab was worth much more a thousand miles south than at the mine. Explain what the buyer in the south was paying for.","Houses built of salt slabs roofed with camel skins. Explain what that one detail tells a historian about the place."],key:["Because the salt was there and almost nowhere else, and the people to the south needed it and had gold. The cost of supplying the miners was high, but the margin between what a slab cost to cut and what it sold for in the Sahel was higher, so the trade paid even after feeding everybody by caravan. A resource that is scarce where it is wanted will be dug out of a place nobody would otherwise live. Partial: naming the salt with nothing said about the margin covering the cost is approaching. (HSS-7.4)","The transport, the risk and the organization, far more than the salt. Two months of camels, men, guides and provisions, the chance of losing the lot, and the money tied up for the whole journey all sit inside that price. Buyers in the south were paying for the distance, which is why the same goods were cheap at one end of a route and dear at the other. Partial: naming the price with nothing said about what the buyer was actually paying for is approaching. (HSS-7.4)","That there was no timber, no stone worth quarrying and no clay, so the only building material to hand was the thing being mined, and the only other material was what the caravans brought. It is evidence of a settlement with no local resources at all, existing solely because of what lay under it, and it confirms how completely the place depended on the caravan trade. Partial: noting the salt-block houses with nothing said about the total dependence on the caravans is approaching. (HSS-7.4) Rating guide for this part, because these three questions sit above the grade-level floor of HSS-7.4. 3: the student explains why salt was worth mining and carrying across the desert, and what the distance added to its price. 2: answers one of those two. 1: answers neither, and gives no account of the salt trade. Where the count of right answers and this guide disagree, rate from the guide and write the count in Notes."]},{std:["HSS-7.3"],n:4,dur:100,dir:"Read the note. Answer out loud.",desc:"analyzing Mongol rule in China and the overland exchange it opened",html:()=>`<p class="big">Mongol armies took northern China and then the south, and from 1271 the Mongol ruler governed as emperor of a new dynasty, the Yuan, from a capital at what is now Beijing. For about a century a single power controlled the overland routes from China to the Black Sea, which made travel across them safer than it had been for centuries. Merchants, envoys, craftsmen and missionaries went both ways; a Venetian merchant’s account of the journey was read all over Europe. The Yuan kept Chinese administration running but filled the top posts with Mongols and foreigners rather than with Chinese scholar officials, and let the examination system lapse for decades. Buddhist, Daoist, Muslim, Nestorian Christian and Jewish communities all operated under Yuan rule.</p>
     <div class="figure">${ico("horse",74)}${ico("map",74)}${ico("books",74)}</div>`,qs:["One power controlling the whole overland route made travel safer. Explain why safety on a route matters more to trade than the distance does.","The Yuan kept Chinese administration but shut Chinese scholars out of the top posts. Explain what that did to the dynasty’s standing with the educated class.","Communities of several religions operated under Yuan rule. Name one practical reason a government ruling such a wide territory would allow that.","Name one thing that traveled the overland routes in this century besides trade goods, and say what it changed."],key:["A long route can be walked if it is safe; a short one cannot be used at all if goods are taken halfway. Crossing a dozen jurisdictions means a dozen sets of tolls, escorts and risks, and the cost of guarding and insuring a cargo can exceed what it is worth. One authority means one set of rules and one party answerable for order, so the real cost of the distance falls. Partial: naming the single authority with nothing said about tolls or risk is approaching. (HSS-7.3)","It cut them off from the careers their whole training was for, so the group that normally supplied the dynasty’s officials, its records and its justification had no stake in it. Many withdrew to teaching, writing and painting instead. A government that does not employ the educated class loses the people who make its administration work and who write how it will be remembered. Partial: noting their exclusion with nothing said about what the government lost by it is approaching. (HSS-7.3)","Any one: the empire already contained many peoples, and suppressing any of them would mean fighting its own subjects; religious leaders who are left alone help keep their communities quiet and can be used to pass on the government’s requirements; foreign merchants and specialists the state wanted would not come without it; and the rulers themselves had no single established religion to impose at first. Partial: calling it kindness with no practical reason named is approaching. (HSS-7.3)","Any one, with the change named: printing, paper money and gunpowder knowledge moved west; mapmaking and travel accounts changed what Europeans thought the world was shaped like and set some of them looking for a sea route; artistic designs and motifs moved in both directions; and the plague of the 1340s traveled the same routes, which is part of why one epidemic reached from China to England. Partial: naming something that moved with no change it caused named is approaching. (HSS-7.3)"]}]},{id:21,title:"Ranks and Marketplaces",short:"Ranks",parts:[{std:["HSS-7.5"],n:3,dur:90,dir:"Look at the chart. Answer out loud.",desc:"analyzing the fixed social ranks of Tokugawa Japan and the strains within them",html:()=>`<p class="big">After 1600 the Japanese government fixed the social order by law. Rank was inherited and movement between ranks was forbidden.</p>
     <table class="bigTable"><tr><th>Rank</th><th>What they did</th><th>Income</th></tr>
     <tr><td>court nobility and the emperor’s household</td><td>ceremony and prestige, no governing</td><td>a fixed allowance</td></tr>
     <tr><td>samurai</td><td>administration, law and arms; many became clerks and officials</td><td>a fixed allowance in rice from their lord</td></tr>
     <tr><td>farmers</td><td>grew the rice everyone else lived on</td><td>what was left after the rice tax</td></tr>
     <tr><td>artisans</td><td>made goods</td><td>what they sold</td></tr>
     <tr><td>merchants</td><td>bought, sold, shipped and lent</td><td>what they earned, which in time was a great deal</td></tr></table>
     <div class="figure">${ico("pine",74)}${ico("coin",74)}${ico("wheat",74)}</div>`,qs:["Merchants were placed at the bottom of the order and ended up the wealthiest group in it. Explain how a ranking can come apart like that.","Samurai were paid a fixed allowance in rice while the economy increasingly used money. Explain the difficulty that created for them.","Two centuries of peace with a warrior class still at the top of the order. Name one thing that class did instead of fighting."],key:["The ranking was built on an older idea of worth, in which producing food and bearing arms counted and trade did not. But the economy that grew up under two centuries of peace ran on shipping, credit and city markets, which is merchants’ work. Law can fix who is respected; it cannot fix who the economy pays. The result was a wealthy group with low status and a high status group in debt to it. Partial: noting the mismatch with no account of what the economy actually ran on is approaching. (HSS-7.5)","A fixed quantity of rice is a fixed income only if rice buys the same as before. As cities grew and merchants prospered, the things a samurai family needed to buy cost more, while the allowance did not change, so its real value fell. Many ended up borrowing from the merchants they officially outranked, which is one of the standing tensions of the period. Partial: naming the fixed allowance with nothing said about prices rising is approaching. (HSS-7.5)","Any one: they ran the administration as clerks, inspectors, accountants and magistrates; they taught, and many turned to scholarship and writing; they managed their lords’ finances and estates; and the martial training continued as a discipline and a mark of rank rather than as preparation for a campaign. Partial: saying they had nothing to do is the misreading to watch for and is approaching. (HSS-7.5)"]},{std:["HSS-7.7"],n:3,dur:90,dir:"Look at the chart. Answer out loud.",desc:"comparing Meso-American market exchange with Andean state redistribution",html:()=>`<p class="big">Two ways of getting goods to the people who wanted them, in two places that had no coinage.</p>
     <table class="bigTable"><tr><th></th><th>The valley of Mexico</th><th>The Inca empire</th></tr>
     <tr><td>How goods moved</td><td>huge daily markets; a Spanish eyewitness estimated tens of thousands of people at the market of Tlatelolco</td><td>no markets of that kind; goods moved into state storehouses and out again by official decision</td></tr>
     <tr><td>Standing in for money</td><td>cacao beans and lengths of cotton cloth, used to measure value and settle small payments</td><td>nothing of the kind; obligations were counted in labor and recorded on knotted cords</td></tr>
     <tr><td>Long distance goods</td><td>professional merchants traveled far for feathers, jade, cacao and metals</td><td>the state moved goods itself, along its own roads, between its own stores</td></tr></table>
     <div class="figure">${ico("corn",74)}${ico("box",74)}${ico("mountain",74)}</div>`,qs:["Explain one advantage of each system for an ordinary household.","Cacao beans used as money, in a place where cacao was also drunk. Name one advantage and one problem with using a food as currency.","The Inca moved goods by official decision rather than by sale. Name one thing that gives a government and one thing it costs."],key:["Market system: a household can choose what it buys, sell what it has made, and respond quickly to what it needs, and a shortage in one thing can be made up by trading something else. State system: a household is not at the mercy of prices, and a bad year in its own district is met from the storehouses rather than by going without, so the floor is higher even though the choice is narrower. Partial: one of the two systems described is approaching. (HSS-7.7)","Advantage: everybody wants it, it is countable and roughly uniform, it is light, and it has value in itself, so it is accepted without anyone having to guarantee it. Problem: it spoils, it can be eaten, a good harvest means suddenly more money in circulation and a bad one means less, and the beans can be hollowed out and refilled, which was a known fraud. Partial: one of the advantage and the problem given is approaching. (HSS-7.7)","Gives: complete control of what each province produces and where it goes, the ability to feed armies and work gangs anywhere, and relief for a district that has failed, all without needing coin or merchants. Costs: it needs an enormous permanent apparatus of counting, storing and transport; it has no way of finding out what people actually want; and the whole thing stops working if the center stops functioning. Partial: one of what it gives and what it costs is approaching. (HSS-7.7)"]}]},{id:22,title:"Plain Language, Plain Instruments",short:"Plain Language",parts:[{std:["HSS-7.8"],n:3,dur:90,dir:"Read the note. Answer out loud.",desc:"analyzing the move from Latin to everyday languages and the reading public it created",html:()=>`<p class="big">For centuries anything serious in western Europe was written in Latin. Dante wrote his long poem in Italian instead and then wrote a defense of doing so. Chaucer wrote in English, Rabelais and Montaigne in French, Cervantes in Spanish. Printers followed the market: by the mid 1500s most of what came off European presses was in the everyday languages rather than Latin. Writers in those languages had to invent or borrow words for ideas that had only ever been discussed in Latin, and grammars and dictionaries were written to settle how the new literary languages should be used.</p>
     <div class="figure">${ico("books",74)}${ico("pencil",74)}${ico("palette",74)}</div>`,qs:["Writing a serious work in the everyday language instead of Latin changes who can read it. Name two other effects.","Writers had to invent words for ideas that existed only in Latin. Explain what that tells you about what a language is.","Grammars and dictionaries were written for these languages. Explain why a printed book makes that necessary."],key:["Any two: it changes who can write, since a merchant or a woman without a Latin education could now take part; it splits the reading public along language lines, so a book that once reached all of educated Europe now reaches one country; it makes writers compete for ordinary readers, which changes what subjects and what style sell; and it gives a language prestige, which feeds into a sense of national identity. Partial: one effect named is approaching. (HSS-7.8)","That a language is not fixed: it can be extended on purpose when its speakers need to say something new, by borrowing, by building words from parts, or by giving an old word a new sense. English, French and Italian took in thousands of words in this period. A language grows to fit what its users are doing with it. Partial: noting the new words with nothing said about a language growing to fit its use is approaching. (HSS-7.8)","A printed book fixes one spelling, one form and one wording in thousands of identical copies, and it is sold to readers hundreds of miles from the writer who speak the language differently. Someone has to decide which form goes in the type, and once a decision is printed everywhere it becomes the standard. Printing turns a loose collection of dialects into a language with rules. Partial: saying printing spread the language with nothing said about one form being fixed is approaching. (HSS-7.8)"]},{std:["HSS-7.9"],n:3,dur:90,dir:"Read the note. Answer out loud.",desc:"analyzing the wars of religion and the practical arguments for toleration that followed",html:()=>`<p class="big">The century and a half after 1540 saw long wars in which religion was one of the main issues: in France between Catholics and Protestants, in the Netherlands against Spanish rule, and across central Europe in the Thirty Years War, which ended in 1648 with much of Germany’s population and economy ruined. Settlements were reached one by one. France granted its Protestants protected rights in 1598, then revoked them in 1685, and about two hundred thousand of them left the country, taking their trades with them. The Dutch Republic took a different route, and allowed several churches to operate while giving one an official position, which made it a refuge for printers, scholars and dissenters from elsewhere.</p>
     <div class="figure">${ico("map",74)}${ico("books",74)}${ico("key",74)}</div>`,qs:["France revoked its Protestants’ rights, and two hundred thousand of them left. Explain the economic effect on France and on the countries that received them.","Toleration was often argued for on practical grounds rather than on principle. Give the practical argument.","The Dutch Republic allowed several churches while giving one an official position. Explain how an arrangement like that can be stable."],key:["France lost skilled workers, merchants and their capital, and lost them to its rivals: silk weavers, watchmakers, printers, bankers and soldiers who settled in England, the Netherlands, Prussia and elsewhere and set up the same trades there. One country’s loss was another’s gain, in exactly the trades a state wanted most. Enforcing uniformity cost France part of its economy. Partial: noting the departures with nothing said about rivals gaining the same trades is approaching. (HSS-7.9)","That trying to compel belief does not work and ruins the country in the attempt: a century of war had not made anyone change their mind, it had destroyed trade, farms and populations, and a state that leaves its subjects alone on this question gets peace, taxpayers and immigrants with skills. The argument is about what works, not about whether the beliefs are right, and that is what made it persuasive to governments. Partial: arguing that the beliefs were right or wrong is beside the point here and is approaching. (HSS-7.9)","It gives the majority church the status, the public position and the funding it wants, so it has no reason to fight, while the other groups get what they most need, which is to be left alone to meet, trade and live. Nobody has to concede that the others are right. A settlement that divides status from freedom of practice can satisfy both sides at once. Partial: naming one side's gain with nothing said about the other's is approaching. (HSS-7.9)"]},{std:["HSS-7.10"],n:3,dur:90,dir:"Look at the chart. Answer out loud.",desc:"analyzing new instruments and how each one turned a quality into a measurable quantity",html:()=>`<p class="big">Four instruments of the 1600s, and what each one let an investigator do for the first time.</p>
     <table class="bigTable"><tr><th>Instrument</th><th>What it made measurable</th></tr>
     <tr><td>the pendulum clock</td><td>short intervals of time, to the second, repeatably</td></tr>
     <tr><td>the sealed thermometer</td><td>how hot something is, on a scale, instead of hot or cold</td></tr>
     <tr><td>the barometer</td><td>the weight of the air, and that it changes with weather and height</td></tr>
     <tr><td>the air pump</td><td>what happens when most of the air is taken out of a vessel</td></tr></table>
     <div class="figure">${ico("clock",74)}${ico("thermometer",74)}${ico("drop",74)}</div>`,qs:["Pick two rows and explain what question each instrument made answerable that could not be settled by argument alone.","A thermometer turns hot and cold into a number on a scale. Explain why that is a bigger step than it sounds.","Two investigators in different countries use the same kind of instrument. Explain what has to be true for their results to be comparable."],key:["Any two handled correctly: the clock made it possible to ask how fast something falls or swings, and to find a rule, since timing to the second is what turns motion into numbers; the thermometer let heat be compared between places and days, so the behavior of air, water and bodies could be studied; the barometer settled whether air has weight and showed that it falls with height, which no amount of reasoning had decided; and the air pump let the question of whether sound, fire or life need air be tested instead of debated. Partial: one instrument matched to what it made possible is approaching. (HSS-7.10)","A quality has no middle: something is hot or it is not, and two people can disagree forever with no way to settle it. A number on a scale can be written down, compared with yesterday’s, compared with a reading from another country, added, averaged and plotted, so a pattern can be found and a rule stated. Turning a quality into a quantity is what lets a subject be investigated at all. Partial: saying numbers are more exact with nothing said about comparing, averaging or plotting is approaching. (HSS-7.10)","The instruments have to be made the same way and agree with each other, which means a standard and a way of checking one against another; the scales have to be fixed to the same reference points; and each must report the procedure as well as the number, so a difference can be traced to the method rather than to the instrument. This is why standards, calibration and detailed published methods became part of the work. Partial: one of the standards, the fixed scales and the published method named is approaching. (HSS-7.10)"]},{std:["HSS-7.11"],n:3,dur:90,dir:"Read the note. Answer out loud.",desc:"analyzing public banks, paper money and the national debt as new financial institutions",html:()=>`<p class="big">In 1694 a group of London merchants lent the English government 1.2 million pounds and were chartered as the Bank of England in return. The loan was not to be repaid as a lump sum: Parliament voted particular taxes to cover the interest, and the debt became permanent. The Bank issued notes, took deposits and dealt in government paper, and the government’s debt could be bought and sold by anyone. The Dutch had done something similar earlier, and over the following century the states with these institutions could borrow far more cheaply than those without.</p>
     <div class="figure">${ico("coin",74)}${ico("books",74)}${ico("key",74)}</div>`,qs:["Parliament voted taxes to cover the interest rather than to repay the loan. Explain why a lender would be content with that.","Government debt could be bought and sold by anyone. Explain what that does for the people who hold it and for the government.","States with these institutions borrowed far more cheaply. Explain what a lower interest rate let a government do."],key:["Because what a lender wants is a reliable income, and a tax voted by Parliament to pay the interest is as close to reliable as the age offered: the people who would pay the tax had agreed to it, and the Bank’s own charter depended on the arrangement holding. The lender also kept an asset he could sell. A permanent debt with a secure income stream is safer than a promise to repay in full one day. Partial: naming the interest with nothing said about why a voted tax made it reliable is approaching. (HSS-7.11)","For the holder it means the money is not locked away: it can be sold whenever cash is needed, so lending to the government is no longer a commitment for life, which brings in far more lenders. For the government it means a market price for its own credit, and a much larger pool of people willing to lend, which is why it could raise sums no earlier treasury could have found. Partial: one of the holder's and the government's side given is approaching. (HSS-7.11)","Fight longer wars, build larger navies, and pay for them out of borrowing rather than by taxing until the country rebelled, with the cost spread over decades of interest. Finance, not just population or territory, became a measure of a state’s power in this period, and it is a large part of why some smaller states outlasted larger ones. Partial: naming the borrowing with nothing said about finance as a measure of power is approaching. (HSS-7.11)"]}]},{id:23,title:"Spring Green",short:"Spring Green",parts:[{std:["LS1"],n:3,dur:90,dir:"Look at the table. Answer out loud.",desc:"using a pondweed trial with two controls to explain what photosynthesis needs and what it produces",html:()=>`<p class="big">A wetland study put the same mass of pondweed in each of four tubes of pond water for one hour.</p>
     <table class="bigTable"><tr><th>Tube</th><th>Light</th><th>Carbon dioxide added to the water</th><th>Oxygen bubbles counted in an hour</th></tr>
     <tr><td>1</td><td>full spring sun</td><td>yes</td><td>196</td></tr>
     <tr><td>2</td><td>full spring sun</td><td>none added</td><td>61</td></tr>
     <tr><td>3</td><td>wrapped in foil</td><td>yes</td><td>0</td></tr>
     <tr><td>4</td><td>full spring sun, pondweed boiled first</td><td>yes</td><td>0</td></tr></table>
     <div class="figure">${ico("drop",74)}${ico("sprout",74)}${ico("sun",74)}</div>`,qs:["Tubes 3 and 4 produced no oxygen for different reasons. Name each reason and the process both failed to carry out.","Tube 1 gave 196 bubbles and tube 2 gave 61. Name what tube 2 was short of, and explain where the oxygen in those bubbles comes from.","The pondweed gains mass over the spring. Say where the matter comes from and what happens to the light energy."],key:["Photosynthesis. Tube 3 had living pondweed and carbon dioxide but no light, since the foil blocked it. Tube 4 had light and carbon dioxide but the pondweed had been boiled, so its cells were dead and could not carry out the process at all. Photosynthesis needs light and a living plant, and removing either one stops it. Partial: naming the reason for one of the two tubes is approaching, and tube 4's boiled pondweed is usually the one left unexplained. (LS1)","Tube 2 was short of carbon dioxide, one of the two raw materials, so it could only use what was already dissolved in the pond water. The oxygen in the bubbles comes from the water and carbon dioxide the plant took in: photosynthesis rearranges those atoms into sugar, and the oxygen atoms left over are released as oxygen gas. Partial: naming the carbon dioxide shortage with nothing said about the bubbles' oxygen coming from the water and carbon dioxide taken in is approaching. (LS1)","Almost all of it comes from the carbon dioxide dissolved in the pond water and from the water itself, whose carbon, hydrogen and oxygen atoms are rearranged into sugar and then into stem and leaf. The light energy does not stay as light: it ends up stored in the chemical bonds of that sugar, which is energy stored in matter and is what the rest of the pond's food chain lives on. Partial: naming the dissolved carbon dioxide and water with nothing said about the light energy ending up in the bonds of the sugar is approaching. (LS1)"]},{std:["LS1"],n:3,dur:90,dir:"Look at the table. Answer out loud.",desc:"using a developing tadpole to explain respiration without feeding and growth from rearranged food molecules",html:()=>`<p class="big">A frog tadpole was weighed and its gas exchange measured at three stages of spring.</p>
     <table class="bigTable"><tr><th>Stage</th><th>Mass</th><th>Oxygen used an hour</th><th>Carbon dioxide made an hour</th><th>What it was eating</th></tr>
     <tr><td>newly hatched</td><td>0.02 g</td><td>0.01 mL</td><td>0.009 mL</td><td>nothing, the egg's yolk only</td></tr>
     <tr><td>growing tadpole</td><td>0.9 g</td><td>0.6 mL</td><td>0.55 mL</td><td>algae scraped off stones</td></tr>
     <tr><td>young frog</td><td>3.4 g</td><td>2.4 mL</td><td>2.2 mL</td><td>insects</td></tr></table>
     <div class="figure">${ico("frog",74)}${ico("drop",74)}${ico("butterfly",74)}</div>`,qs:["The newly hatched tadpole eats nothing yet still produces carbon dioxide. Name the process and say what molecules it is using.","The animal went from 0.02 g to 3.4 g. Explain where the matter for that growth came from and what had to happen to it first.","Oxygen used an hour rose from 0.01 mL to 2.4 mL. Explain the two different things that larger number is paying for."],key:["Cellular respiration. It is breaking down the food molecules stored in the egg's yolk, mainly fats and proteins, using oxygen, and rearranging their atoms into carbon dioxide and water, which releases the energy those bonds held. Even an animal that is not eating is respiring, because its cells need that energy continuously. Partial: naming cellular respiration with nothing said about the yolk's stored food molecules being what it is breaking down is approaching. (LS1)","From the yolk at first, then from the algae and then the insects it ate. Those food molecules had to be digested, broken into smaller units such as amino acids, sugars and fatty acids, which the animal's cells then rearranged into its own muscle, skin, bone and membranes. Growth is food atoms taken apart and rebuilt into the animal's own molecules, not matter appearing from nowhere. Partial: naming the food eaten with nothing said about it having to be digested into smaller units before being rebuilt is approaching. (LS1)","It pays for both energy and building. A larger body has more cells all respiring to run themselves, to move and to keep working, so the demand rises simply with size. On top of that, growth itself costs energy, because building a new protein or a new membrane out of food units takes energy released by respiration. So the rise reflects a bigger animal and an animal actively adding material at the same time. Partial: accounting for the larger body's demand with nothing said about growth itself costing energy, or the other way round, is approaching. (LS1)"]}]},{id:24,title:"The Meadow Comes Back",short:"Meadow",parts:[{std:["LS2"],n:3,dur:95,dir:"Look at the table. Answer out loud.",desc:"using differently managed strips to identify limiting conditions and name predation",html:()=>`<p class="big">Four meadow strips were managed differently for three years. Counts were taken this spring.</p>
     <table class="bigTable"><tr><th>Strip</th><th>Mowing</th><th>Water</th><th>Flowering plant species</th><th>Bumblebees in 20 minutes</th><th>Voles per 100 traps</th></tr>
     <tr><td>1</td><td>cut once in late summer</td><td>spring wet, dries in June</td><td>24</td><td>31</td><td>9</td></tr>
     <tr><td>2</td><td>cut every three weeks</td><td>spring wet, dries in June</td><td>6</td><td>4</td><td>2</td></tr>
     <tr><td>3</td><td>cut once in late summer</td><td>kept wet by a leaking pipe</td><td>11</td><td>14</td><td>7</td></tr>
     <tr><td>4</td><td>cut once in late summer</td><td>spring wet, dries in June</td><td>23</td><td>29</td><td>1, a kestrel hunts here</td></tr></table>
     <div class="figure">${ico("daisy",74)}${ico("bee",74)}${ico("eagle",74)}</div>`,qs:["Compare strips 1 and 2. Name what limited the flowering plants and the bees, and give the numbers.","Strip 3 was kept wet all summer and has fewer flowering species than strip 1. Explain how more water can mean fewer species.","Strip 4 has almost the same plants and bees as strip 1 but only 1 vole per 100 traps. Explain, and name the interaction."],key:["The chance to flower and set seed, removed by cutting every three weeks. Strip 1, cut once in late summer, has 24 flowering species and 31 bumblebees; strip 2, cut every three weeks, has 6 and 4. The plants cannot reach flowering before each cut, so most species are lost, and the bees lose the nectar and pollen they feed on, which is their limiting resource. Partial: naming the cutting as the cause with the 24 and 31 against 6 and 4 not quoted is approaching. (LS2)","Permanently wet ground suits only the plants that tolerate it, and a few vigorous wetland species then spread and shade out the rest, so species that need the ground to dry in June are lost. Strip 1's seasonal wetting and drying is a condition that many different species are suited to in turn. More of a resource is not automatically better; the condition that suits the most species is what matters, and competition between plants decides the rest. Partial: saying wet ground suits fewer plants, with nothing said about a few vigorous species spreading and shading the rest out, is approaching. (LS2)","Predation, with the kestrel as predator and the vole as prey. Strip 4's food and cover for voles are as good as strip 1's, so the shortage is not of resources; it is that something is taking them. A population is set both by the resources available and by other species that affect it, so two places with identical resources can hold very different numbers. Partial: naming the kestrel with nothing said about strip 4's resources being as good as strip 1's is approaching. (LS2)"]},{std:["LS2"],n:3,dur:95,dir:"Look at the table. Answer out loud.",desc:"explaining energy loss along a chain, matter cycling through decomposers, and a solution after a nearby disruption",html:()=>`<p class="big">A year of measurements from one square meter of the restored meadow and its pond edge.</p>
     <table class="bigTable"><tr><th>Step</th><th>Who is in it</th><th>Energy stored in a year (kJ per square meter)</th></tr>
     <tr><td>producers</td><td>meadow grasses, flowers, pondweed, algae</td><td>9,100</td></tr>
     <tr><td>plant eaters</td><td>voles, caterpillars, tadpoles, snails</td><td>880</td></tr>
     <tr><td>animal eaters</td><td>kestrels, frogs, dragonflies, beetles</td><td>71</td></tr>
     <tr><td>decomposers</td><td>fungi, bacteria, worms in the thatch and pond mud</td><td>all the matter returns here</td></tr></table>
     <p>A neighboring field was drained and sprayed, and within two springs the pond at its edge held no tadpoles and its hedge was gone.</p>
     <div class="figure">${ico("purpleFlower",74)}${ico("frog",74)}${ico("mushroom",74)}</div>`,qs:["The three numbers fall to about a tenth each step. Account for the missing energy and say what it means for how many kestrels a meadow can hold.","A phosphorus atom in a dead meadow flower turns up in next year's flower. Describe its path and name what does each step.","Predict two effects on this meadow of the neighboring field being drained and sprayed. Then name one thing that could be done to protect this meadow's variety of life. Give the reason it works."],key:["Most was released as thermal energy while the organisms moved, fed and kept their bodies going, and a share stayed in parts never eaten, such as roots, stems, shells and droppings, which pass to the decomposers. Only about a tenth is stored in the step above. So a square meter capturing 9,100 kJ supports only 71 kJ of kestrels, frogs, dragonflies and beetles, and a kestrel needs a great many square meters. The number of predators is set by the energy the plants captured. Partial: naming the thermal energy with nothing said about the number of kestrels being set by the energy the plants captured is approaching. (LS2)","The flower dies and falls into the thatch, where decomposers, fungi, bacteria and worms, break it down and release its phosphorus into the soil as a mineral compound. A root takes that compound up with water and the plant builds it into a new flower. Matter cycles and the same atom can be used again and again; energy does not, because it left as thermal energy during respiration, which is why the sun has to supply it afresh each year. Partial: tracing the phosphorus back into a flower with nothing said about matter cycling while energy does not is approaching. (LS2)","Effects, any two: the dragonflies, frogs and bees that used both the field's pond and hedge and this meadow lose half their habitat, so their numbers here fall; with the hedge gone there is nothing to shelter this meadow's edge from wind and spray drift; the kestrel loses hunting ground, so it hunts this strip harder, which presses the voles further; and water draining off the bare field can carry soil and spray into this pond. A protection with a reason, any one: plant a wide hedge and an uncut strip along the boundary, because a buffer catches spray drift and run off before it reaches the pond and gives the insects shelter; keep the pond and meadow connected to another patch of good habitat, because a species lost in one place can only come back if there is somewhere for it to come back from; and keep part of the meadow uncut each year, because the insects that overwinter in stems need somewhere the mower has not been. Partial: two effects predicted with a protection named but no reason given for why it works is approaching. (LS2)"]}]},{id:25,title:"What the Wetland Is Built On",short:"Wetland",parts:[{std:["MS-ESS2"],n:3,dur:90,dir:"Look at both tables. Answer out loud.",desc:"reading a wetland core for its depositing agents and comparing geoscience rates over two thousand years",html:()=>`<p class="big">A core was taken through the wetland, and the study group keeps measured rates.</p>
     <table class="bigTable"><tr><th>Depth</th><th>What it is</th><th>What is in it</th></tr>
     <tr><td>0 to 40 cm</td><td>dark peat</td><td>reed stems not yet rotted, pollen grains</td></tr>
     <tr><td>40 to 120 cm</td><td>gray clay in fine flat bands</td><td>water flea shells, no sand</td></tr>
     <tr><td>120 to 180 cm</td><td>sorted sand and rounded gravel</td><td>pebbles of three rock types</td></tr>
     <tr><td>below 180 cm</td><td>unsorted mud, sand and angular boulders</td><td>boulders scratched on one face</td></tr></table>
     <table class="bigTable"><tr><th>Process</th><th>Rate measured here</th></tr>
     <tr><td>peat building up in the wetland</td><td>1 mm a year</td></tr>
     <tr><td>the brook cutting into the peat bank</td><td>7 cm a year</td></tr>
     <tr><td>the valley floor rising as the crust recovers</td><td>2 mm a year</td></tr>
     <tr><td>the bank slumping into the brook in one wet spring</td><td>60 cm in one month</td></tr></table>
     <div class="figure">${ico("mountain",74)}${ico("drop",74)}${ico("leaf",74)}</div>`,qs:["Name what deposited the bottom layer and what deposited the sand and gravel above it, and say how the sorting tells you.","The clay has fine flat bands and water flea shells, and the peat above it has reed stems and pollen. Describe how this place changed over time, and say which layer is oldest.","Peat builds at 1 mm a year and the valley rises at 2 mm a year, while the bank can slump 60 cm in a month. Work out the peat and the uplift over 2,000 years and say why a scientist needs records of both the slow and the sudden."],key:["The bottom layer was left by ice. A glacier carries every size at once and drops it all together when it melts, so nothing is sorted, and it scratches the boulders it drags against bedrock. The sand and gravel above was deposited by running water, because moving water carries only the sizes its speed allows and leaves the rest, which sorts the deposit and rounds the pebbles. Sorting records the agent. Partial: naming the ice and the water correctly with no account of the sorting being what told you is approaching. (MS-ESS2)","The bottom layer is oldest, since each layer was laid down on the one before. The place went from under or at the edge of an ice sheet, to a fast meltwater stream depositing sand and gravel, to a still lake where only fine clay settled and water fleas lived, to a shallow reed wetland where dead plants piled up faster than they could rot and became peat. The core reads as a history from the bottom up. Partial: naming the bottom layer as the oldest with two or three of the four stages described is approaching. (MS-ESS2)","At 1 mm a year the peat builds 2,000 mm, which is 2 m, and at 2 mm a year the valley rises 4,000 mm, which is 4 m. Both are invisible in a lifetime. A slump of 60 cm in a month is visible in a single spring. Both records are needed because the slow rates explain why the wetland exists at all and what it will be in a thousand years, while the sudden events explain what the brook bank does this year, and a plan built on only one of the two gets the other wrong. Partial: working out one of the two 2,000 year figures, or both with nothing said about why records of the sudden are needed too, is approaching. (MS-ESS2)"]},{std:["MS-ESS2"],n:3,dur:90,dir:"Look at the table. Answer out loud.",desc:"using seafloor age, earthquake depth and matching coal sequences to explain plate motion",html:()=>`<p class="big">The pebbles in the sand and gravel layer were traced to rock 60 km north. A geologist left the study group three charts.</p>
     <table class="bigTable"><tr><th>Chart</th><th>What it says</th></tr>
     <tr><td>ocean floor ages across a ridge</td><td>at the ridge, new; 130 km out, 3 million years; 520 km out, 12 million years; 1,040 km out, 24 million years, matching both sides</td></tr>
     <tr><td>earthquake depths near a trench</td><td>shallow at the trench, deepening along a slope that runs down under the neighboring plate to about 650 km</td></tr>
     <tr><td>rock and fossil matches</td><td>the same 310 million year old coal and fossil fern sequence runs along two coasts now 5,800 km apart</td></tr></table>
     <div class="figure">${ico("map",74)}${ico("compass",74)}${ico("shell",74)}</div>`,qs:["The ages increase outwards equally on both sides. Say what is happening at the ridge and the rate the first pair of figures gives.","Earthquakes get deeper along a slope running under the neighboring plate. Explain what that is evidence for, and why it matters that no ocean floor is older than about 200 million years.","One 310 million year old coal and fern sequence runs along two coasts 5,800 km apart. Explain what that is evidence for, and why coal is good evidence."],key:["New ocean floor is being made at the ridge and carried away in both directions, so rock is older the further it has traveled. 130 km in 3 million years is 130,000 m in 3,000,000 years, which is about 4.3 cm a year on each side, so the plates separate at about 8.7 cm a year. Partial: describing the sea floor spreading with the 4.3 cm a year not worked out from the 130 km and 3 million years is approaching. (MS-ESS2)","It is evidence that a slab of ocean floor bends down at the trench and sinks into the mantle, with the quakes marking where the cold slab breaks and grinds on the way down. That is how ocean floor is destroyed. It matters because it explains why no sea floor is older than about 200 million years while continental rock is billions of years old: the sea floor is made at ridges and recycled at trenches, so none of it lasts, while the lighter continents stay at the surface. Partial: saying the quakes trace a sinking slab with nothing said about why that explains the young age of all ocean floor is approaching. (MS-ESS2)","It is evidence that the two coasts were one piece of land when those swamp forests grew, and that the plates carrying them have moved apart since, with an ocean opening between. Coal is good evidence because it forms from a connected swamp forest laid down over a long time in one place, and a swamp cannot form in two pieces 5,800 km apart and end up with the same age, the same sequence and the same fossil fern. Partial: saying the coasts were joined with nothing said about why coal is strong evidence is approaching. (MS-ESS2)"]}]},{id:26,title:"What a Wetland Is Worth",short:"Worth",parts:[{std:["MS-ESS3"],n:3,dur:90,dir:"Look at the table. Answer out loud.",desc:"classifying resources and explaining how the same period left two very different ones",html:()=>`<p class="big">The district's resource map lists what the valley has and why.</p>
     <table class="bigTable"><tr><th>Resource</th><th>Where it is</th><th>The past process that put it there</th></tr>
     <tr><td>the gravel aquifer</td><td>under the valley floor</td><td>meltwater sorted and dumped sand and gravel as the ice sheet retreated, and rain now soaks into it</td></tr>
     <tr><td>peat</td><td>the wetland itself</td><td>waterlogged ground where dead reeds could not fully rot, building about a millimeter a year</td></tr>
     <tr><td>brick clay</td><td>the lake clay layer under the wetland</td><td>fine mud settled in a still lake after the ice left</td></tr>
     <tr><td>limestone</td><td>the ridge 20 km south</td><td>a warm shallow sea whose shells and mud were pressed into rock</td></tr>
     <tr><td>spring sunshine and wind on the ridge</td><td>above the valley</td><td>the sun arriving every day, and the uneven heating that drives wind</td></tr></table>
     <div class="figure">${ico("wind",74)}${ico("drop",74)}${ico("mountain",74)}</div>`,qs:["Decide which of these five are renewable and which are not, and use the process column to defend one of your decisions.","The gravel aquifer and the brick clay were both left at the end of the last ice age but do opposite jobs. Explain how one period produced two such different resources, and why neither is everywhere.","The district could dig the peat for fuel and the clay for bricks, and both lie above the aquifer. Name one benefit and one cost, and say what makes them hard to weigh against each other."],key:["Renewable: the sunshine and wind, which keep arriving, and the aquifer water, refilled each year by rain soaking into the gravel. Nonrenewable in any useful sense: the peat, the brick clay and the limestone. The peat defends the point: it builds at about a millimeter a year, so a meter of it is a thousand years' worth, and cutting it away takes something that cannot be put back in a human lifetime. Partial: all five sorted correctly with no defense drawn from the process column is approaching. (MS-ESS3)","The two were deposited by different agents in the same period. Fast meltwater sorted its load and dropped sand and gravel, which has spaces between the grains, so it holds and releases water. A still lake let only the finest mud settle, and fine mud packed together is clay, which holds water back instead of letting it through. Neither is everywhere because meltwater rivers and still lakes were only in certain places, so each resource exists where its process happened and nowhere else. Partial: contrasting the gravel and the clay with nothing said about why neither is everywhere is approaching. (MS-ESS3)","Benefit: fuel and bricks from close at hand, cheap to haul, and work for people in the district. Cost: digging the peat removes a store built over thousands of years and releases its carbon, and digging through to the clay opens the ground above the aquifer, so what is spilled at the surface can reach the water the district drinks. They are hard to weigh because the benefit arrives now and can be counted in money, while the cost arrives slowly, falls partly on people who come later, and is a loss of something that cannot be bought back. Partial: a benefit and a cost named with nothing said about why they are hard to weigh against each other is approaching. (MS-ESS3)"]},{std:["MS-ESS3"],n:3,dur:90,dir:"Look at the table. Answer out loud.",desc:"ordering hazard monitoring by warning time and matching responses to the warning available",html:()=>`<p class="big">The wetland station watches two spring hazards that decide when the group can work on the boardwalk: flooding of the brook, and a slip in the peat bank. The boardwalk is closed and empty whenever a watch is on.</p>
     <table class="bigTable"><tr><th>What is watched</th><th>What it reports</th><th>Useful warning</th></tr>
     <tr><td>the regional weather model</td><td>rainfall expected over the catchment</td><td>2 to 6 days</td></tr>
     <tr><td>rain gauges in the upper catchment</td><td>rain that has already fallen upstream</td><td>5 to 12 hours before the brook rises</td></tr>
     <tr><td>a soil moisture and tilt probe in the peat bank</td><td>how wet and how far tilted the bank is</td><td>1 to 4 days</td></tr>
     <tr><td>a brook level gauge at the boardwalk</td><td>the water level where the group works</td><td>minutes</td></tr>
     <tr><td>100 years of flood and slip records with a map of the ground each flood covered</td><td>how often, and how far</td><td>no timing</td></tr></table>
     <div class="figure">${ico("cloud",74)}${ico("drop",74)}${ico("board",74)}</div>`,qs:["Order the first four from the most warning to the least, and name the row that gives no warning of a coming event.","The group is choosing now where to rebuild a section of boardwalk. Which row helps most, and why is a forecast no use for that choice?","The tilt probe gives days and the brook gauge gives minutes. Name one measure suited to each, and say what the difference in warning time means for how a plan has to be made."],key:["Most to least: the weather model, 2 to 6 days, and the soil moisture and tilt probe, 1 to 4 days; the upper catchment rain gauges, 5 to 12 hours; the brook gauge at the boardwalk, minutes. The 100 years of records and the flood map give no warning of a coming event, since they report how often and how far, not when the next one will come. Partial: the four instruments ordered correctly with the 100 year record and the flood map not identified as giving no timing is approaching. (MS-ESS3)","The 100 years of records and the flood map, because they show which ground the brook has reached and how often, so the boardwalk can be routed over ground the record says stays firm and built high enough for the floods the record says are likely. A forecast is no use because it covers only the next few days while a boardwalk has to last years. A forecast decides whether to work today; a record decides where it is sensible to build at all. Partial: naming the records and the flood map with nothing said about why a forecast cannot settle a route is approaching. (MS-ESS3)","With days of warning a decision can still be taken then: close that section, move the tools and timber off the bank, reroute the day's work, and bring in props. With minutes, only what is already installed can act: a gate that swings shut, a marked exit route, an alarm wired to the gauge, and a deck built so water passes under it. The difference means that the shorter the warning, the more of the response has to be designed and built in advance, and the longer the warning, the more can be left to a decision on the day. Partial: both kinds of measure named with nothing said about the warning time deciding how much has to be built in advance is approaching. (MS-ESS3)"]}]},{id:27,title:"The Field Laboratory",short:"Matter",parts:[{std:["MS-PS1"],n:3,dur:95,dir:"Look at the table. Answer out loud.",desc:"classifying substances from atomic models, judging evidence for a reaction, and applying conservation of mass",html:()=>`<p class="big">Four substances in the field kit were tested.</p>
     <table class="bigTable"><tr><th>Substance</th><th>What one particle is made of</th><th>Melting point</th><th>In water</th></tr>
     <tr><td>garden lime (calcium carbonate)</td><td>calcium, carbon and oxygen atoms in a repeating grid</td><td>breaks down above 800 C</td><td>barely dissolves</td></tr>
     <tr><td>copper in the probe wire</td><td>copper atoms only</td><td>1,085 C</td><td>does not dissolve</td></tr>
     <tr><td>hydrogen peroxide in the test bottle</td><td>2 hydrogen and 2 oxygen atoms joined</td><td>-0.4 C</td><td>mixes completely</td></tr>
     <tr><td>ammonium nitrate from the cold pack</td><td>nitrogen, hydrogen and oxygen atoms in a repeating grid</td><td>170 C</td><td>dissolves, solution carries a current</td></tr></table>
     <p>A drop of hydrogen peroxide was put on a crushed piece of liver. Before: a clear colorless liquid and a dark red solid. After: a thick foam of bubbles, a liquid that can no longer bleach a cloth, and a gas that made a glowing splint flare. The dish and contents weighed 72.4 g before and 71.6 g after with the lid off, and 72.4 g both times in a sealed tube.</p>
     <div class="figure">${ico("drop",74)}${ico("pan",74)}${ico("leaf",74)}</div>`,qs:["Which one is an element, and what in the particle column shows it? Then say how many atoms are in one hydrogen peroxide particle and why it is a compound even with only two kinds of atom.","Give two pieces of evidence for a chemical reaction, and say why a foam appearing is stronger evidence than the mixture getting warm.","Explain both mass results and what they show about the atoms."],key:["Copper, because one particle is copper atoms only, one kind of atom and nothing else. One hydrogen peroxide particle has 2 + 2 = 4 atoms. It is a compound because it has two different kinds of atom, hydrogen and oxygen, joined in a fixed ratio; a compound needs two or more kinds, and two is enough. Partial: naming the copper and counting the 4 atoms with nothing said about two kinds of atom being enough to make a compound is approaching. (MS-PS1)","Any two: a gas was produced where none existed before, and it makes a glowing splint flare, which is a property of oxygen and of neither starting substance; the liquid can no longer bleach a cloth, so the hydrogen peroxide is no longer there; and the bubbles mean a new substance in a new state. A foam of a new gas is stronger evidence than warmth because dissolving something can warm or cool a mixture with nothing new made, while a gas that was not present in either starting substance has to have been made. Partial: two pieces of evidence given with nothing said about dissolving also changing a mixture's temperature is approaching. (MS-PS1)","Both show the atoms were only rearranged. In the sealed tube the oxygen that formed could not escape, so every atom stayed inside and the mass held at 72.4 g. With the lid off, 0.8 g of that oxygen left into the room, so the dish weighs less while the total mass of the dish, its contents and the escaped gas is unchanged. Mass is conserved in a chemical reaction; only an open container loses track of the gaseous products. Partial: saying the oxygen escaped from the open dish, with nothing said about the total mass including the escaped gas being unchanged, is approaching. (MS-PS1)"]},{std:["MS-PS1"],n:3,dur:90,dir:"Look at the table. Answer out loud.",desc:"interpreting a melting curve, comparing natural and synthetic materials, and specifying a cooling device",html:()=>`<p class="big">A block of frozen pond water was warmed on a steady hotplate and read at the times shown.</p>
     <table class="bigTable"><tr><th>Minute</th><td>0</td><td>3</td><td>6</td><td>36</td><td>56</td><td>76</td><td>86</td><td>96</td></tr>
     <tr><th>Temperature (C)</th><td>-14</td><td>-7</td><td>0</td><td>0</td><td>0</td><td>0</td><td>13</td><td>27</td></tr></table>
     <p>The study group's nets are nylon made from oil. Its notebooks are paper from a spruce plantation.</p>
     <div class="figure">${ico("thermometer",74)}${ico("butterfly",74)}${ico("pencil",74)}</div>`,qs:["The hotplate setting never changed, yet the reading held at 0 from minute 6 to minute 76. Describe what the particles were doing, and say what they did before and after.","Name the resource behind the net and the notebook, the kind of change that makes each, and which can be replaced.","Water samples have to stay below 6 degrees for five hours on the walk back, with no power. Describe a device that absorbs thermal energy from the samples, say what the change inside it must do with energy, and name one measurement that would show whether it meets the need."],key:["Before minute 6 the arriving energy made the particles in the solid vibrate faster, which is what a rising temperature measures. From minute 6 to 76 it went into breaking the attractions holding the particles in the fixed ice arrangement, freeing them to slide past one another, which is melting, so they did not speed up and the thermometer held at 0. That stretch is much the longest because separating every particle takes far more energy than warming the solid did. After minute 76 it was all liquid and the arriving energy again made the particles move faster, so the reading climbed. Partial: naming the melting with nothing said about the arriving energy breaking the attractions rather than speeding the particles up is approaching. (MS-PS1)","The net comes from crude oil, a nonrenewable resource, and the oil's molecules are reacted to build long new molecules that were not in the oil, a chemical change, which is what makes nylon synthetic. The notebook comes from spruce wood, a renewable resource, and the wood is pulped, pressed and dried, which keeps the same fiber, so that part is physical, though bleaching and sizing add chemical steps. A spruce plantation regrows in decades; the oil took over 100 million years. Partial: both resources named with the physical and chemical change not told apart is approaching. (MS-PS1)","A cold pack in the carrier: ammonium nitrate and water, which take energy in as the solid dissolves, or a sealed ice pack, which takes energy in as it melts. In both the change is endothermic: it draws energy in from the surroundings, so the samples give energy up and cool. A measurement, any one with a target: the sample temperature at hourly intervals, the hours it stays below 6 degrees, and the degrees of cooling per gram of pack, which says how many packs a five hour walk needs. Partial: naming a cold pack with no measurement given, or with the change not identified as one that takes energy in, is approaching. (MS-PS1)"]}]},{id:28,title:"Crossing the Wet Ground",short:"Design",parts:[{std:["MS-ETS1"],n:3,dur:85,dir:"Look at the table. Answer out loud.",desc:"defining a design problem with criteria and constraints and comparing competing designs",html:()=>`<p class="big">A 50 m stretch of path crosses soft wet peat. It has to carry one person with a 15 kg pack without sinking, be built by 3 people in a day, and be removable in autumn. The group has planks, chestnut palings, geotextile, gravel, rope and 120 pounds.</p>
     <table class="bigTable"><tr><th>Design</th><th>Sinking under a loaded walker</th><th>Build time, 3 people</th><th>Cost</th><th>Removable in autumn</th></tr>
     <tr><td>A: gravel spread straight on the peat</td><td>11 cm</td><td>5 hours</td><td>90 pounds</td><td>no, the gravel sinks in and stays</td></tr>
     <tr><td>B: planks laid on the peat</td><td>7 cm</td><td>3 hours</td><td>60 pounds</td><td>yes</td></tr>
     <tr><td>C: geotextile, then gravel on top</td><td>3 cm</td><td>7 hours</td><td>115 pounds</td><td>no</td></tr>
     <tr><td>D: paling mats on geotextile</td><td>2 cm</td><td>9 hours</td><td>105 pounds</td><td>yes, the mats roll up</td></tr></table>
     <div class="figure">${ico("board",74)}${ico("sprout",74)}${ico("pack",74)}</div>`,qs:["Write the problem in one sentence naming what has to be achieved, with no material in it.","Set out two criteria and two constraints for this path, and mark each one as a criterion or a constraint.","Using the table, say which designs fail a constraint and which best meets the criteria, and name the trade off in your choice."],key:["Something like: carry one walker with a 15 kg pack across 50 m of soft wet peat without sinking, built by 3 people in a day for 120 pounds, and taken up again in the autumn. It names the load, the distance, the ground, the labor, the budget and the removability, and names no plank, gravel or mat. Partial: a sentence that names mats or planks rather than the result to be achieved is approaching. (MS-ETS1)","Criteria: little or no sinking under a loaded walker, and the less the better. Constraints: 3 people for one day, a 120 pound budget, 50 m of soft peat, a 15 kg pack, the materials on hand, and that it must come up again in the autumn. A criterion measures how good the result is; a constraint is a limit the design may not break. Partial: two criteria and one constraint, or one of each, is approaching. (MS-ETS1)","A fails because it cannot be removed, and it is also the worst on sinking at 11 cm. C fails on removability and is 115 pounds, close to the limit. D meets every constraint, since 9 hours is within a day for 3 people and 105 pounds is inside the budget and the mats roll up, and it is best on sinking at 2 cm. The trade off is build time: D costs 9 hours against B's 3, so B would be the choice if labor were the scarcest thing, at the price of 7 cm of sinking rather than 2. Partial: choosing D with nothing said about A and C failing the removability requirement, or with no trade off named against B, is approaching. (MS-ETS1)"]},{std:["MS-ETS1"],n:3,dur:90,dir:"Look at the table. Answer out loud.",desc:"analyzing test data to improve a design and explaining iterative testing",html:()=>`<p class="big">The paling mat path was tested four times over the same 50 m with the same loaded walker.</p>
     <table class="bigTable"><tr><th>Test</th><th>What changed</th><th>Sinking (cm)</th><th>Build time</th><th>Note from the run</th></tr>
     <tr><td>1</td><td>mats on geotextile as built</td><td>2</td><td>9 hours</td><td>mats slide apart at the joins</td></tr>
     <tr><td>2</td><td>mats laced together with rope at the joins</td><td>2</td><td>10 hours</td><td>no sliding, joins held</td></tr>
     <tr><td>3</td><td>laced mats, and the geotextile left out</td><td>6</td><td>8 hours</td><td>mats pressed into the peat and wet through</td></tr>
     <tr><td>4</td><td>laced mats on geotextile, and a thin layer of gravel on top</td><td>1</td><td>12 hours</td><td>gravel works down between the palings</td></tr></table>
     <div class="figure">${ico("pencil",74)}${ico("ruler",74)}${ico("board",74)}</div>`,qs:["Which change fixed the fault test 1 revealed, and what did it cost?","Test 3 removed the geotextile. Say what it tells you about that layer, and whether removing it was worth the hour it saved.","Test 4 gave the best sinking figure and a new problem. Name the problem, and say why test 4 is not the end of the work."],key:["Test 2's lacing. Test 1's note said the mats slid apart at the joins, and lacing them with rope stopped that with no loss of performance, since sinking stayed at 2 cm. It cost one extra hour of build time. The change answered the fault the run had reported rather than changing something that was not failing. Partial: naming the lacing with its one hour cost or the unchanged 2 cm of sinking not given is approaching. (MS-ETS1)","It tells you the geotextile is doing most of the work of spreading the load. Without it, sinking went from 2 cm to 6 cm, three times as much, and the mats pressed into the peat and got wet, which will rot them. It saved one hour of build time and cost three quarters of the design's performance, so it was not worth it. Because only one thing changed, the geotextile's own contribution can be stated, which is the point of changing one variable at a time. Partial: noting that sinking got worse without the geotextile with no judgment given on whether the saved hour was worth it is approaching. (MS-ETS1)","The gravel works down between the palings, which means it will not stay on top, it adds weight into the mat, and it will make the mats much harder to roll up in the autumn, which is a constraint. Test 4 is not the end because it reached 1 cm of sinking while breaking a requirement the table does not score, and because each test here was a single run with one walker on one day. The design is changed by what the tests reveal and then tested again, including for the autumn lift, which is what makes design a cycle. Partial: naming the gravel working down with nothing said about it putting the autumn lift at risk is approaching. (MS-ETS1)"]}]}];const LEVELUPS={1:{id:"L1",title:"Level Up: Theme and the Plot It Rides On",std:["RL.8.2"],needs:["RL.7.2"],n:2,dir:"Answer out loud. Read me the lines you are relying on.",html:()=>`<ol class="qlist"><li>Analyze how the theme you named is shaped by the characters and the setting, not only by what Dovie does. Use at least two details.</li><li>The story could have ended at “They had the remaining six ribs in before five thirty.” What does the June paragraph add to the theme, and why does the writer keep Dovie's change private?</li></ol>${story(true)}`,key:["Two or more details tied to character and setting. Selena is built as the opposite of a speech: “Selena had not been asked, and she did not ask anything either,” and her only argument is the sentence already printed on the box. The setting supplies the argument too: the box itself says TWO PERSON JOB, and the twelve sockets measure Dovie's method against a clock she cannot argue with, three hours for four ribs against about four minutes each. Mr. Abara's sign makes the credit a physical object. The theme is carried by those as much as by Dovie's choices. (RL.8.2, how a theme is shaped by characters and setting)","The June paragraph is where the theme is tested rather than demonstrated. Finishing the ribs only shows that two people are faster; the sign shows what Dovie does once the credit is already hers and nobody is watching. Keeping it private, “She did not tell anybody. Selena saw it in September,” rules out the reading that she was performing fairness for an audience, and the four-month gap makes it a settled change rather than a gesture. (RL.8.2, analyzing a theme's development and its relationship to the plot)"]},2:{id:"L2",title:"Level Up: Letters on Both Sides",std:["8.EE.C.7"],needs:["7.EE.B.4"],n:3,dir:"Work on your paper and hold it up. Show every step and check your answer.",html:()=>`<ol class="qlist"><li>Solve 5x − 3 = 2x + 12.</li><li>Solve 4(x − 2) = 4x − 8. How many solutions does it have, and what does that mean?</li><li>Solve 3(x + 4) = 3x + 10. How many solutions does it have, and what does that mean?</li></ol>`,key:["x = 5. Steps: subtract 2x from both sides to get 3x − 3 = 12, then 3x = 15, so x = 5. Check: 5(5) − 3 = 22 and 2(5) + 12 = 22. (8.EE.C.7b, variables on both sides)","Infinitely many solutions. Expanding the left side gives 4x − 8 = 4x − 8, which is true for every value of x, because the two sides are the same expression. (8.EE.C.7a)","No solution. Expanding gives 3x + 12 = 3x + 10, and subtracting 3x leaves 12 = 10, which is never true, so no value of x works. (8.EE.C.7a)"]},3:{id:"L3",title:"Level Up: Idea, Detail, Summary",std:["RI.8.2"],needs:["RI.7.2"],n:2,dir:"Answer out loud. Read me the lines you are relying on.",html:()=>`<ol class="qlist"><li>Pick the central idea you think the article most wants kept. Analyze how the writer develops it, including how the supporting ideas and the specific numbers serve it.</li><li>Write an objective summary in exactly two sentences that keeps both central ideas and no examples.</li></ol>${article(true)}`,key:["Usually the second idea, that a germination test turns an unknown into a number you plant with. The development runs through the whole piece: the first three paragraphs build the uncertainty the test answers, and every number is doing one job in that build. Two years and five years show that the kind matters, the under-100 rule and the 95 degree garage show that storage matters, and the six out of ten is the only number that comes out of the reader's own kitchen. The closing pair, “not a pass or a fail” and “a number you plant with,” states the idea the rest was arranged to reach. (RI.8.2, development of a central idea through supporting ideas and details)","Exactly two sentences, both central ideas, no examples. For instance: the date on a seed packet records only when the seed was packed, so whether the seed will grow depends on the kind and on how it was stored. A ten seed germination test gives the grower a percentage in about a week, and that percentage tells the grower how thickly to sow rather than whether to sow at all. Mark it down if a particular crop, temperature, or the paper towel appears, or if a third sentence is used. (RI.8.2, objective summary)"]},5:{id:"L5",title:"Level Up: Angles That Have To Add Up",std:["8.G.A.5"],needs:["7.G.A.2"],n:3,dir:"Work on your paper and hold it up. Write the reasoning, not just the number.",html:()=>`<ol class="qlist"><li>A triangle has angles of 3x, 4x, and 5x. Find all three angles.</li><li>One exterior angle of a triangle measures 110°, and one of the two remote interior angles is 45°. Find the other remote interior angle.</li><li>Triangle 1 has angles of 40° and 75°. Triangle 2 has angles of 75° and 65°. Are the two triangles similar? How do you know?</li></ol>`,key:["45°, 60°, and 75°. The three angles add to 180°, so 3x + 4x + 5x = 12x = 180 and x = 15. Then 3(15) = 45, 4(15) = 60, and 5(15) = 75. Check: 45 + 60 + 75 = 180. (8.G.A.5, the angle sum of a triangle)","65°. An exterior angle equals the sum of the two remote interior angles, so 110 − 45 = 65. Check: the third angle is 180 − 110 = 70, and 45 + 65 + 70 = 180. (8.G.A.5, the exterior angle of a triangle)","Yes, they are similar. Triangle 1's third angle is 180 − 40 − 75 = 65°, so its angles are 40°, 65°, and 75°. Triangle 2's third angle is 180 − 75 − 65 = 40°, so its angles are the same three. Two pairs of equal angles are enough, which is the angle-angle criterion. (8.G.A.5, the AA criterion for similarity)"]},6:{id:"L6",title:"Level Up: Round Solids",std:["8.G.C.9"],needs:["7.G.B.6"],n:3,dir:"Work on your paper with a calculator. Give the exact answer in terms of pi and then round to the nearest tenth.",mats:["a calculator"],html:()=>`<ol class="qlist"><li>A cylindrical rain barrel has a radius of 1 foot and a height of 4 feet. What is its volume?</li><li>A cone of screened soil has a base radius of 3 feet and is 2 feet tall. What is its volume?</li><li>A spherical float has a radius of 3 inches. What is its volume?</li></ol>`,key:["4π cubic feet, which is about 12.6. The volume of a cylinder is πr²h, so π × 1² × 4 = 4π = 12.566… (8.G.C.9)","6π cubic feet, which is about 18.8. The volume of a cone is one third of πr²h, so (1/3) × π × 3² × 2 = (1/3) × 18π = 6π = 18.849… Forgetting the one third gives 56.5, which is the cylinder. (8.G.C.9)","36π cubic inches, which is about 113.1. The volume of a sphere is (4/3)πr³, so (4/3) × π × 27 = 36π = 113.097… (8.G.C.9)"]},7:{id:"L7",title:"Level Up: Verbals, Voice, and Mood",std:["L.8.1"],needs:["L.7.1"],n:3,dir:"Say each answer out loud. When you fix a sentence, say the whole sentence the correct way.",html:()=>`<ol class="qlist"><li>“Sighting down the pipe took longer than seating it.” Which word is the verbal, what kind is it, and what job does it do in the sentence?</li><li>Say this in active voice: “The seventh rib was carried to the socket by Selena.”</li><li>Fix the shift in voice: “Dovie set the rib, and then the socket was straightened by her.”</li></ol>`,key:["Sighting. A gerund. With its phrase, “Sighting down the pipe,” it is the subject of the sentence, so it is doing the job of a noun. (L.8.1a, verbals)","Selena carried the seventh rib to the socket. (L.8.1b, active and passive voice)","Dovie set the rib and then straightened the socket. Both verbs are now active, and the sentence no longer switches voice halfway through. (L.8.1d, correcting a shift in voice)"]}};const READ_STD=["RL.7.2","RL.7.6","RL.7.9","RI.7.2","RI.7.8","RI.7.9","L.7.4","RL.8.2","RI.8.2"];const WRITE_STD=["W.7.1","W.7.2","W.7.3","W.7.8"];const MATH_STD=["7.RP.A.2","7.RP.A.3","7.NS.A.3","7.EE.B.3","7.EE.B.4","7.G.A.2","7.G.B.4","7.G.B.6","7.SP.B.4","7.SP.C.8","8.EE.C.7","8.G.A.5","8.G.C.9"];const TEXT_STD=READ_STD.concat(["W.7.2"]);const dl=a=>`<dl>${a.map(x=>`<dt>${x[0]}</dt><dd>${x[1]}</dd>`).join("")}</dl>`;const ul=a=>`<ul class="card-list">${a.map(x=>`<li>${x}</li>`).join("")}</ul>`;const G_STORY=[["hoop house","an unheated greenhouse made of bent pipe ribs covered in plastic"],["rib","one of the bent pipes that make the arch of a hoop house"],["socket","the short pipe driven into the ground that a rib slides into"],["kit","everything needed for a build, packed and sold together"],["custodian","the person who looks after a school building"],["drainage","where the water goes when it leaves a site"],["proposal","a written plan asking for permission or money"]];const G_SEED=[["viable","still alive and able to grow"],["germinate","to sprout and begin growing from a seed"],["germination rate","the share of a sample of seeds that sprout, written as a percent"],["relative humidity","how much moisture the air holds compared with the most it could hold at that temperature"],["seed saver","somebody who keeps seed from one season to sow the next"],["tendency","what usually happens, which is not the same as a rule"]];function glossHtml(st){const s=st.std||[];return dl(s.includes("RI.7.2")||s.includes("W.7.2")||s.includes("RI.8.2")||s.includes("L.7.4")?G_SEED.concat(G_STORY):G_STORY)}const TERMS=[["theme","a statement about people or life that the whole text supports, not the subject and not the plot"],["central idea","the main point a nonfiction text is making, which may be more than one"],["development","how a writer builds an idea across a text, piece by piece"],["objective summary","a summary with no opinion, no praise, and no blame in it"],["context clue","a word or phrase nearby that narrows down what an unknown word means"],["etymology","the part of a dictionary entry that gives a word's origin"],["root","the core of a word that carries its meaning, such as therm for heat"],["affix","a prefix or a suffix added to a root"]];const FRAMES={"RL.7.2":["A theme of this story is ____.","It starts to show when ____.","It develops when ____.","By the end, ____.","Objective summary: ____."],"RI.7.2":["One central idea is ____.","A second central idea is ____.","The writer develops the first by ____.","The second depends on the first because ____."],"L.7.4":["I think ____ means ____.","The words “____” nearby told me.","The root ____ means ____.","To check it I would look at the ____ part of the entry."],"SL.7.4":["My claim is ____.","My first finding is ____, because the table shows ____.","My second finding is ____.","For example, ____.","The other side has ____.","I am asking the council to ____."],"W.7.1":["The council should ____.","Some would argue that ____. However, ____.","The fact box shows ____, which matters because ____.","As a result, ____.","For these reasons, ____."],"W.7.2":["The date on a seed packet tells you ____, and it does not tell you ____.","First, ____.","Second, ____. For example, ____.","Instead of guessing, ____.","In short, ____."],"W.7.3":["It was ____ when ____.","At first, ____.","“____,” ____ said.","By the time ____, ____.","Looking back, ____."],"RL.7.6":["The narration follows ____, because ____.","____ sees the job as ____, while ____ sees it as ____.","The line “____” shows the difference.","Holding back ____ lets the reader ____."],"RL.7.9":["The log records ____. The story adds ____.","A record leaves out ____ because ____.","Both agree that ____.","The author invents in the gaps by ____."],"RI.7.8":["The claim is ____.","The reasons given are ____ and ____.","The evidence for ____ is relevant because ____.","It is not enough, because the letter never ____."],"RI.7.9":["Source P leans on ____. Source Q leans on ____.","Both mention ____, but P reads it as ____ and Q reads it as ____.","That difference comes from ____."],"W.7.8":["Better search terms: ____ and ____, because each one names ____.","Source ____ is more credible here because ____.","Quotation: “____” (____).","Paraphrase: ____."]};function framesHtml(st){const s=st.std||[];const k=["RL.7.2","RL.7.6","RL.7.9","RI.7.2","RI.7.8","RI.7.9","L.7.4","SL.7.4","W.7.1","W.7.2","W.7.3","W.7.8"].find(x=>s.includes(x))||"RL.7.2";return`<ul class="starters" style="font-size:1.18rem">${FRAMES[k].map(x=>`<li>${x}</li>`).join("")}</ul>`}function gramHtml(){return`<h4>Where a modifier goes</h4>`+ul(["A modifier attaches to whatever it sits next to, so put it next to the word it is about.","<strong>Misplaced:</strong> the modifier is in the sentence but beside the wrong word. Move it.","<strong>Dangling:</strong> the thing the modifier is about is not in the sentence at all. Add it, or rewrite the clause.","Watch only, just, almost, and nearly. They limit whatever follows them."])+`<h4>Phrases and clauses</h4>`+dl([["Phrase","a group of words with no subject and verb pair of its own. <em>about a third of the way up</em>"],["Independent clause","has a subject and a verb and can stand alone. <em>Dovie read the line</em>"],["Subordinate clause","has a subject and a verb but cannot stand alone. <em>although the box said four hours</em>"]])+`<h4>Four kinds of sentence</h4>`+F.table(["Kind","What it holds"],[["Simple","one independent clause"],["Compound","two or more independent clauses"],["Complex","one independent clause plus at least one subordinate clause"],["Compound-complex","two or more independent clauses plus at least one subordinate clause"]])}const MULT_N=12;let multSel=[0,0];function multHtml(){let h=`<div class="tool-scroll"><table class="mult"><tr><th>×</th>`;for(let c=1;c<=MULT_N;c++)h+=`<th data-r="0" data-c="${c}" class="${multSel[1]===c?"hl":""}">${c}</th>`;h+="</tr>";for(let r=1;r<=MULT_N;r++){h+=`<tr><th data-r="${r}" data-c="0" class="${multSel[0]===r?"hl":""}">${r}</th>`;for(let c=1;c<=MULT_N;c++){const hr=multSel[0]===r,hc=multSel[1]===c;h+=`<td data-r="${r}" data-c="${c}" class="${hr&&hc?"pick":hr||hc?"hl":""}">${r*c}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to light up its row and column. Click it again to clear.</p>`}let calcE="",calcAns="";function calcEval(){let e=calcE.replace(/×/g,"*").replace(/÷/g,"/").replace(/−/g,"-").replace(/π/g,"Math.PI").replace(/\^/g,"**").replace(/√\(/g,"Math.sqrt(");if(!/^[0-9+\-*/().\sMathPIsqrt]*$/.test(e)||!e)return"";try{const o=(e.match(/\(/g)||[]).length-(e.match(/\)/g)||[]).length;if(o>0)e+=")".repeat(o);const v=Function('"use strict";return ('+e+")")();return Number.isFinite(v)?String(+v.toPrecision(10)):"Error"}catch(x){return"Error"}}function calcHtml(){const keys=["7","8","9","÷","⌫","4","5","6","×","(","1","2","3","−",")","0",".","^","+","C","√(","π","="];return`<div class="calc-disp" aria-live="polite">${calcE||"0"}${calcAns!==""?`<br><strong>= ${calcAns}</strong>`:""}</div><div class="calc-keys">${keys.map(k=>`<button data-k="${k}" class="${k==="="?"eq":/[0-9.]/.test(k)?"":"op"}">${k==="^"?"xʸ":k==="√("?"√":k}</button>`).join("")}</div><p class="small">Press √ then the number and close the bracket. The π key enters pi.</p>`}function calcBind(b,r){b.querySelectorAll("[data-k]").forEach(x=>x.onclick=()=>{const k=x.dataset.k;if(k==="C"){calcE="";calcAns=""}else if(k==="⌫"){calcE=calcE.replace(/(√\(|.)$/,"");calcAns=""}else if(k==="="){calcAns=calcEval()}else{if(calcAns!==""&&calcAns!=="Error"&&/^[+−×÷^]/.test(k))calcE=calcAns;else if(calcAns!=="")calcE="";calcAns="";calcE+=k}r()})}const FORM={"7.EE.B.4":["Equations and inequalities",ul(["Say what your letter stands for before you write the equation.","Undo the operations in reverse order, doing the same thing to both sides.","p(x + q) = r can be divided by p first, or expanded first. Both work.","An inequality is solved the same way, with one exception: multiplying or dividing by a negative flips the sign.","Then read the answer back into the situation. You cannot buy 38.9 trays."])],"7.G.A.2":["Conditions on a triangle",ul(["<strong>Three sides:</strong> exactly one triangle, provided any two of them add to more than the third.","<strong>Two sides and the angle between them:</strong> exactly one triangle.","<strong>Three angles that add to 180°:</strong> infinitely many triangles, all the same shape and different sizes.","<strong>Three angles that do not add to 180°:</strong> no triangle.","<strong>Two sides that are too short to span the third:</strong> no triangle."])],"7.G.B.6":["Area, surface area, volume",`<table class="meas"><tr><th>Rectangle</th></tr><tr><td class="formula">A = base × height</td></tr><tr><th>Triangle</th></tr><tr><td class="formula">A = 1/2 × base × height</td></tr><tr><th>Trapezoid</th></tr><tr><td class="formula">A = (base 1 + base 2) ÷ 2 × height</td></tr><tr><th>Right prism</th></tr><tr><td class="formula">V = B × h, where B is the base area</td></tr></table>`+ul(["A composite shape: cut it into rectangles and triangles, find each area, then add.","A closed box has three pairs of matching faces. An open box is missing one of them.","Area is in square units. Volume is in cubic units."])],"7.RP.A.2":["Proportional relationships",ul(["A relationship is proportional when every pair of values gives the same ratio y/x.","That shared ratio is the constant of proportionality, k, and the equation is y = kx.","On a graph a proportional relationship is a straight line through the origin, and (1, k) is on it."])],"7.RP.A.3":["Percent problems",ul(["A % off leaves (100 - A)% of the price. A % added gives (100 + A)% of the price.","Percent increase or decrease = the change divided by the ORIGINAL amount.","Do the steps in the order the situation does them: discount first, then tax on what is left."])],"7.NS.A.3":["Rational number arithmetic",ul(["Adding a negative is the same as subtracting; subtracting a negative is the same as adding.","A fraction of an amount means multiply: 2/5 of 14.75 is 14.75 x 2 ÷ 5.","Keep the units and the sign with the number the whole way through."])],"7.EE.B.3":["Estimating and checking",ul(["Round every number to something you can hold in your head, work it through, and keep that figure.","Convert between fractions, decimals and percents whenever one form is easier.","Compare the exact answer with the estimate. If they are far apart, one of them is wrong."])],"7.G.B.4":["Circles",`<table class="meas"><tr><th>Circumference</th></tr><tr><td class="formula">C = 2πr = πd</td></tr><tr><th>Area</th></tr><tr><td class="formula">A = πr²</td></tr></table>`+ul(["The diameter is twice the radius. Halve it before using the area formula.","Cut a circle into thin wedges and lay them alternately: the shape is close to a rectangle of length πr and height r, which is why A = πr².","Circumference is in units. Area is in square units."])],"7.SP.B.4":["Comparing two samples",ul(["Mean: the total divided by how many. Median: the middle value in order.","Mean absolute deviation: the average distance of the values from the mean.","Compare the gap between the two centers with the variability inside each sample. A gap several times the MAD is a real difference; a gap smaller than the MAD is not much."])],"7.SP.C.8":["Compound events",ul(["List the outcomes in an organized way: a table, a tree, or a systematic list.","Independent events: multiply the probabilities.","At least one: find the probability of none and subtract it from 1. Adding the single probabilities double counts."])],"8.EE.C.7":["Linear equations in one variable",ul(["Expand any brackets, then collect the letters on one side and the numbers on the other.","If the two sides end up identical, every number works: infinitely many solutions.","If the letters cancel and leave a false statement, no number works: no solution."])],"8.G.A.5":["Angles in triangles",ul(["The three angles of a triangle add to 180°.","An exterior angle equals the sum of the two remote interior angles.","Two pairs of equal angles make two triangles similar. That is the angle-angle criterion."])],"8.G.C.9":["Round solids",`<table class="meas"><tr><th>Cylinder</th></tr><tr><td class="formula">V = πr²h</td></tr><tr><th>Cone</th></tr><tr><td class="formula">V = (1/3)πr²h</td></tr><tr><th>Sphere</th></tr><tr><td class="formula">V = (4/3)πr³</td></tr></table>`+ul(["A cone is one third of the cylinder with the same base and height.","Give the exact answer in terms of π first, then round."])]};function formHtml(st){const seen=[];return(st.std||[]).filter(x=>FORM[x]).map(x=>{if(seen.includes(x))return"";seen.push(x);return`<h4 style="margin:8px 0 2px">${FORM[x][0]}</h4>${FORM[x][1]}`}).join("")}const TOOLS={gloss:{name:"Word help",std:TEXT_STD.concat(WRITE_STD,["SL.7.4","L.7.1"]),html:glossHtml},terms:{name:"Reading terms",std:READ_STD,html:()=>dl(TERMS)},frames:{name:"Answer frames",std:READ_STD.concat(WRITE_STD,["SL.7.4"]),html:framesHtml},gram:{name:"Grammar card",std:["L.7.1","L.8.1"],html:gramHtml},mult:{name:"Multiplication chart",std:MATH_STD,html:multHtml,bind:(b,r)=>b.querySelectorAll("[data-r]").forEach(c=>c.onclick=()=>{const x=+c.dataset.r,k=+c.dataset.c;multSel=multSel[0]===x&&multSel[1]===k?[0,0]:[x,k];r()})},calc:{name:"Calculator",std:MATH_STD,html:calcHtml,bind:calcBind},form:{name:"Formula and rule card",std:Object.keys(FORM),html:formHtml}};const SUP_CAVEATS=[{t:"passage",std:TEXT_STD,msg:"If the text was read to the student, this stop shows listening comprehension, not reading."},{t:"passage",std:["SL.7.4","W.7.1"],msg:"If the fact box or the table was read aloud, note it. The checks on this stop still stand."},{t:"gloss",std:TEXT_STD,msg:"Word help defines the subject vocabulary. Rate the reasoning and the evidence, not the vocabulary."},{t:"gloss",std:["L.7.4"],msg:"Word help defines viable, germinate, relative humidity, socket, and rib, which are several of the words this stop asks about. Count those items as supported, not independent."},{t:"terms",std:READ_STD,msg:"The reading terms card defines theme, central idea, development, objective summary, context clue, root, and etymology, so this stop then shows applying those ideas with a reference."},{t:"frames",msg:"Answer frames give the sentence structure. Rate the content and the evidence the student supplied."},{t:"frames",std:["RL.7.2","RI.7.2"],msg:"The frames name theme, development, and summary in order, so count the organization of the answer as supported and rate what the student put in each slot."},{t:"frames",std:WRITE_STD.concat(["SL.7.4"]),msg:"Sentence frames supply the order, the linking words, and the closing, so count those checks as supported, not independent."},{t:"gram",std:["L.7.1","L.8.1"],msg:"The grammar card explains misplaced and dangling modifiers, names the four sentence types, and defines phrase and clause, so this stop shows using a reference rather than recall."},{t:"mult",std:MATH_STD,msg:"The multiplication chart supplies the facts. Rate the setup and the reasoning."},{t:"calc",std:["7.EE.B.4","8.EE.C.7"],msg:"The calculator does the arithmetic. Rate whether the student built the right equation or inequality and handled the negative correctly."},{t:"calc",std:["7.G.B.6","8.G.C.9"],msg:"The calculator has a pi key and a square root key, so rate whether the student chose the right formula and the right unit, not the computation."},{t:"form",std:["7.EE.B.4","8.EE.C.7"],msg:"The card gives the solving steps and the rule about flipping an inequality, so count those answers as supported, not independent."},{t:"form",std:["7.G.A.2"],msg:"The card lists every case this stop asks about, one triangle, many, or none, so the stop then shows matching a case to a rule rather than reasoning it out. Write that on the record sheet."},{t:"form",std:["7.G.B.6","8.G.C.9"],msg:"The card gives every formula on this stop, so count those answers as supported and rate the setup and the units."},{t:"form",std:["8.G.A.5"],msg:"The card states the angle sum, the exterior angle rule, and the angle-angle criterion, so count those answers as supported."},{t:"form",std:["7.RP.A.2"],msg:"The card states the equal-ratio test, names the constant, and gives y = kx, which is all three answers on that stop. Count them as supported and rate the arithmetic and the explanation."},{t:"form",std:["7.RP.A.3"],msg:"The card gives the discount-then-tax order and says percent change is measured against the original, so count those answers as supported, not independent."},{t:"form",std:["7.NS.A.3","7.EE.B.3"],msg:"The card gives the sign rules and the estimate-then-compare routine, so count the method as supported and rate whether the student carried the signs and the units through."},{t:"form",std:["7.G.B.4"],msg:"The card gives both circle formulas and the wedge argument, so the third question then shows retelling a stated derivation rather than producing one. Write that on the record sheet."},{t:"form",std:["7.SP.B.4"],msg:"The card defines mean absolute deviation and says to compare the gap with the variability, so count the inference as supported and rate the computation."},{t:"form",std:["7.SP.C.8"],msg:"The card gives the multiply rule and the at-least-one method, so count those answers as supported, not independent."},{t:"calc",std:["7.RP.A.3","7.NS.A.3","7.EE.B.3","7.G.B.4","7.SP.B.4"],msg:"The calculator does the arithmetic, including the percent steps and the mean. Rate whether the student set each one up correctly and kept the units."},{t:"frames",std:["RL.7.6","RL.7.9","RI.7.8","RI.7.9","W.7.8"],msg:"The frames name what each answer has to contain, so count the shape of the answer as supported and rate the evidence the student chose."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:TEXT_STD}}});
